fn stable_builtin_call_user_func(target: &RegionCallTarget) -> bool {
    matches!(
        target,
        RegionCallTarget::Function { name, .. }
            if name.trim_start_matches('\\').eq_ignore_ascii_case("call_user_func")
    )
}

