        self.execution_poll = self
            .execution_poll
            .map(|helper| helper.with_runtime(runtime));
        self.frame_alloc = self.frame_alloc.map(|helper| helper.with_runtime(runtime));
        self.frame_release = self
            .frame_release
            .map(|helper| helper.with_runtime(runtime));
        self.object_release_prepare = self
