    fn with_terminal_exit(mut self, terminal_exit: NativeTerminalExit) -> Self {
        self.execution_poll = self
            .execution_poll
            .map(|helper| helper.with_terminal_exit(terminal_exit));
        self.frame_alloc = self
            .frame_alloc
            .map(|helper| helper.with_terminal_exit(terminal_exit));
        self.frame_release = self
            .frame_release
            .map(|helper| helper.with_terminal_exit(terminal_exit));
        self
    }
