/// Runtime entrypoints are a Generic-tier capability. The optimizing tier
/// deliberately has no variant carrying helper addresses, so an optimizing
/// artifact cannot acquire a generic warm-runtime import by accident.
#[derive(Clone, Copy, Debug)]
#[allow(clippy::large_enum_variant)]
enum NativeTierOperations {
    Generic {
        dynamic_code: Option<NativeHelper>,
        operations: GenericNativeOperations,
        exact_operations: NativeOptimizingOperations,
        value_release_commit: FuncId,
    },
    Optimizing {
        operations: NativeOptimizingOperations,
        argument_contract: Option<NativeHelper>,
    },
}

impl GenericNativeOperations {
    fn with_runtime(mut self, runtime: ir::Value) -> Self {
        self.argument_check = self
            .argument_check
            .map(|helper| helper.with_runtime(runtime));
        self.return_check = self.return_check.map(|helper| helper.with_runtime(runtime));
        self
    }

    fn with_terminal_exit(mut self, terminal_exit: NativeTerminalExit) -> Self {
        self.argument_check = self
            .argument_check
            .map(|helper| helper.with_terminal_exit(terminal_exit));
        self.return_check = self
            .return_check
            .map(|helper| helper.with_terminal_exit(terminal_exit));
        self
    }
}

fn call_native_helper(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    helper: NativeHelper,
    arguments: &[ir::Value],
) -> ir::Inst {
    let callee = module.declare_func_in_func(helper.function, builder.func);
    let runtime = helper
        .runtime
        .expect("native helper must be bound to the request fast-state value");
    let mut direct_arguments = Vec::with_capacity(arguments.len() + 1);
    direct_arguments.push(runtime);
    direct_arguments.extend_from_slice(arguments);
    builder.ins().call(callee, &direct_arguments)
}

fn call_native_pure_handler(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    helper: NativeHelper,
    arguments: &[ir::Value],
) -> ir::Inst {
    debug_assert!(
        helper.runtime.is_none(),
        "pure native handler must not be bound to request state"
    );
    let callee = module.declare_func_in_func(helper.function, builder.func);
    builder.ins().call(callee, arguments)
}

fn native_php_entry_signature(module: &JITModule) -> Signature {
    let pointer_type = module.target_config().pointer_type();
    let mut signature = module.make_signature();
    signature.params.push(AbiParam::new(pointer_type));
    signature.params.push(AbiParam::new(pointer_type));
    signature.params.push(AbiParam::new(pointer_type));
    signature.params.push(AbiParam::new(types::I32));
    signature.params.push(AbiParam::new(pointer_type));
    // `JitNativeControlResult` is returned as two integer ABI words. The
    // first contains the u32 status/detail pair and the second is the native
    // encoded value. Generic and Optimizing entries use this exact signature.
    signature.returns.push(AbiParam::new(types::I64));
    signature.returns.push(AbiParam::new(types::I64));
    signature
}

fn return_native_php_control(
    builder: &mut FunctionBuilder<'_>,
    status: ir::Value,
    result_out: ir::Value,
) {
    let status_word = if builder.func.dfg.value_type(status) == types::I64 {
        status
    } else {
        builder.ins().uextend(types::I64, status)
    };
    let value = builder
        .ins()
        .load(types::I64, MemFlagsData::new(), result_out, 0);
    builder.ins().return_(&[status_word, value]);
}

fn return_native_or_fragment_control(
    builder: &mut FunctionBuilder<'_>,
    status: ir::Value,
    result_out: ir::Value,
) {
    if builder.func.signature.returns.len() == 2 {
        return_native_php_control(builder, status, result_out);
    } else {
        debug_assert_eq!(builder.func.signature.returns.len(), 1);
        builder.ins().return_(&[status]);
    }
}

fn unpack_native_php_control(
    builder: &mut FunctionBuilder<'_>,
    call: ir::Inst,
    result_out: ir::Value,
) -> ir::Value {
    let results = builder.inst_results(call);
    let status_word = results[0];
    let value = results[1];
    builder
        .ins()
        .store(MemFlagsData::new(), value, result_out, 0);
    builder.ins().ireduce(types::I32, status_word)
}

fn compile_managed_native(
    request: &JitCompileRequest,
    function: FunctionId,
    function_key: NativeFunctionKey,
    admission: NativeCompileAdmission,
    specialization: &str,
    helpers: &[(&str, usize)],
    compile: impl FnOnce(
        &mut JITModule,
        &mut cranelift_codegen::Context,
        &mut FunctionBuilderContext,
        &str,
    ) -> Result<(JitFunctionHandle, u64), CraneliftLoweringError>,
) -> Result<ManagedJitFunction, CraneliftLoweringError> {
    let compiled_unit = request
        .ir_fingerprint
        .clone()
        .unwrap_or_else(|| format!("unfingerprinted-function-{}", function.raw()));
    let identity = crate::cranelift_host_isa_identity().map_err(|error| {
        CraneliftLoweringError::new("JIT_CRANELIFT_REJECT_NATIVE_TARGET", error.to_string())
    })?;
    let config_hash = if request.config_hash == 0 {
        identity.feature_fingerprint ^ u64::from(request.opt_level)
    } else {
        request.config_hash
    };
    let mut helper_binding_hash = 0xcbf2_9ce4_8422_2325_u64;
    for (symbol, address) in helpers {
        for byte in symbol.as_bytes().iter().chain(address.to_le_bytes().iter()) {
            helper_binding_hash ^= u64::from(*byte);
            helper_binding_hash = helper_binding_hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    let dependency_identity = request
        .dependency_identity
        .clone()
        .unwrap_or_else(|| format!("ir:{compiled_unit}"));
    let compiler_tier = if request.opt_level < 2 {
        "generic"
    } else {
        "optimizing"
    };
    let key = CraneliftCodeKey {
        compiled_unit,
        region: if request.opt_level < 2 {
            // Generic identity is the authoritative source function, not the
            // caller-provided compilation label used by diagnostics.
            format!("function:{}", function.raw())
        } else {
            format!("{}:function:{}", request.region_id, function.raw())
        },
        abi_hash: JIT_RUNTIME_ABI_HASH,
        compiler_tier: compiler_tier.to_owned(),
        helper_abi_hash: JIT_RUNTIME_ABI_HASH
            ^ crate::JIT_HELPER_REGISTRY_ABI_HASH
            ^ php_runtime::api::NATIVE_OPERATION_ABI_HASH,
        helper_binding_hash,
        target_cpu: format!(
            "{}:{}:{}",
            identity.target_triple, identity.isa_name, identity.feature_fingerprint
        ),
        semantic_config_hash: request.config_hash,
        dependency_identity,
        config_hash,
        invalidation_generation: request.invalidation_generation,
        specialization: specialization.to_owned(),
    };
    let manager = global_code_manager().map_err(|error| {
        CraneliftLoweringError::new("JIT_CRANELIFT_CODE_MANAGER", error.to_string())
    })?;
    manager
        .compile_once_with_scratch_admission(key, Some(function_key), admission, helpers, compile)
        .map_err(|error| match error {
            ManagedCompileError::Manager(error) => {
                CraneliftLoweringError::new("JIT_CRANELIFT_CODE_MANAGER", error.to_string())
            }
            ManagedCompileError::Compile(error) => error,
        })
}

#[cfg(test)]
fn runtime_helper_symbol(base: &str, address: usize) -> String {
    format!("{base}_{address:016x}")
}

fn native_helper_import_symbol(base: &str, address: usize) -> String {
    #[cfg(test)]
    {
        runtime_helper_symbol(base, address)
    }
    #[cfg(not(test))]
    {
        let _ = address;
        base.to_owned()
    }
}

const COLD_DYNAMIC_UNIT_RESOLVE_SYMBOL: &str = "phrust_cold_dynamic_unit_resolve";

/// Mandatory Cranelift native compiler.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct CraneliftNativeCompiler;

impl NativeCompilerApi for CraneliftNativeCompiler {
    fn compile_region(&mut self, request: &NativeCompileRequest<'_>) -> NativeCompileOutcome {
        compile_authoritative_region(request)
    }
}

fn compile_authoritative_region(request: &NativeCompileRequest<'_>) -> NativeCompileOutcome {
    let (Some(unit), Some(function)) = (request.unit, request.function) else {
        return NativeCompileOutcome::skipped(
            JitCompileStatus::Rejected {
                reason: "JIT_CRANELIFT_REJECT_MISSING_IR".to_owned(),
            },
            format!(
                "Cranelift native compiler missing IR context for region `{}`",
                request.compile.region_id
            ),
        );
    };
    let isa = match crate::cranelift_host_isa_identity() {
        Ok(isa) => isa,
        Err(error) => {
            return NativeCompileOutcome::skipped(
                JitCompileStatus::Rejected {
                    reason: error.code.to_owned(),
                },
                error.to_string(),
            );
        }
    };
    let deployment_unit = request
        .compile
        .deployment_identity
        .clone()
        .unwrap_or_else(|| crate::stable_ir_fingerprint(unit));
    // Publishing the unit entry establishes every symbolic function cell for
    // the deployment. A later function-on-demand miss must only ensure its own
    // cell exists; rebuilding the complete declaration set for every called
    // function makes lazy compilation repeatedly scale with source-unit size.
    let declaration_ids: Box<dyn Iterator<Item = FunctionId>> = if function == unit.entry {
        Box::new(
            (0..unit.functions.len())
                .filter_map(|index| u32::try_from(index).ok())
                .map(FunctionId::new),
        )
    } else {
        Box::new(std::iter::once(function))
    };
    let declarations = declaration_ids.filter_map(|function_id| {
        let function = unit.functions.get(function_id.index())?;
        Some(native_function_key(
            deployment_unit.clone(),
            function_id.raw(),
            function.params.len(),
            function.local_count,
            request.compile.opt_level >= 2,
            request.compile.invalidation_generation,
        ))
    });
    let manager = match global_code_manager() {
        Ok(manager) => manager,
        Err(error) => {
            return NativeCompileOutcome::skipped(
                JitCompileStatus::Rejected {
                    reason: "JIT_CRANELIFT_CODE_MANAGER".to_owned(),
                },
                error.to_string(),
            );
        }
    };
    if let Err(error) = manager.declare_function_cells(declarations) {
        return NativeCompileOutcome::skipped(
            JitCompileStatus::Rejected {
                reason: "JIT_CRANELIFT_DECLARE_NATIVE_UNIT".to_owned(),
            },
            error.to_string(),
        );
    }
    let metadata = CompileMetadata {
        ir_fingerprint: request
            .compile
            .ir_fingerprint
            .clone()
            .unwrap_or_else(|| crate::stable_function_ir_fingerprint(unit, function)),
        tier: if request.compile.opt_level < 2 {
            NativeCompilerTier::Generic
        } else {
            NativeCompilerTier::Optimizing
        },
        helper_abi_hash: runtime_helper_abi_hash(request.runtime_helpers),
        target_cpu: format!(
            "{}:{}:{}",
            isa.target_triple, isa.isa_name, isa.feature_fingerprint
        ),
        semantic_config_hash: request.compile.config_hash,
        dependency_identity: request
            .compile
            .dependency_identity
            .clone()
            .unwrap_or_else(|| format!("unit-{}-version-{}", unit.id.raw(), unit.version)),
    };
    let mut compile = request.compile.clone();
    compile
        .ir_fingerprint
        .get_or_insert_with(|| metadata.ir_fingerprint.clone());
    compile
        .deployment_identity
        .get_or_insert_with(|| deployment_unit.clone());
    compile
        .dependency_identity
        .get_or_insert_with(|| metadata.dependency_identity.clone());
    for specialization in &compile.method_specializations {
        let crate::JitMethodSpecializationTarget::Linked(signature) = &specialization.target else {
            continue;
        };
        if !compile
            .external_function_signatures
            .iter()
            .any(|candidate| candidate.link_index == signature.link_index)
        {
            compile.external_function_signatures.push(signature.clone());
        }
    }
    let region = match GenericRegionBuilder::build_with_runtime_specializations(
        unit,
        function,
        &metadata,
        &compile.external_function_signatures,
        &compile.method_specializations,
    ) {
        Ok(region) => region,
        Err(error) => {
            return NativeCompileOutcome::skipped(
                JitCompileStatus::Rejected {
                    reason: error.code.to_owned(),
                },
                error.to_string(),
            );
        }
    };
    if let Err(error) = region.verify() {
        return NativeCompileOutcome::skipped(
            JitCompileStatus::Rejected {
                reason: "JIT_CRANELIFT_FRAGMENT_NORMALIZE".to_owned(),
            },
            format!("normalized native Region IR failed verification: {error}"),
        );
    }
    let plan = compact_native_compile_plan(&region);
    if plan.function != function {
        return NativeCompileOutcome::skipped(
            JitCompileStatus::Rejected {
                reason: "JIT_CRANELIFT_REJECT_COMPILE_PLAN_ROOT".to_owned(),
            },
            format!(
                "native compile plan root {} does not match requested function {}",
                plan.function.raw(),
                function.raw()
            ),
        );
    }
    let start = Instant::now();
    match executable_region::compile_region_graph_native(
        unit,
        region,
        plan,
        request.runtime_helpers,
        &compile,
    ) {
        Ok(compiled) => {
            let elapsed = start.elapsed().as_nanos().try_into().unwrap_or(u64::MAX);
            NativeCompileOutcome::compiled(
                compiled.handle,
                format!(
                    "Cranelift {} Region IR `{}` function={} compilation_mode={} abi_hash={} code_bytes={} clif_blocks={} max_fragment_clif_blocks={} max_fragment_clif_values={} max_fragment_clif_instructions={} max_fragment_block_parameters={} max_fragment_clif_loads={} max_fragment_clif_stores={} max_fragment_loads_per_source_instruction_milli={} max_fragment_stores_per_source_instruction_milli={} max_temporary_cache_entries={} fragment_frame_slots={} fragment_shared_register_slots={} fragment_scratch_register_slots={} pre_regalloc_replans={} fast_path_hits={} control_flow={} plan_ir_instructions={} plan_php_blocks={} plan_estimated_clif_blocks={} plan_virtual_values={} plan_safepoints={} plan_live_sum={} plan_fragments={} plan_max_fragment_blocks={} plan_max_fragment_instructions={} plan_max_fragment_estimated_clif_blocks={}",
                    if compiled.compilation_mode.is_generic() {
                        "Generic"
                    } else {
                        "Optimizing"
                    },
                    request.compile.region_id,
                    function.raw(),
                    compiled.compilation_mode.as_str(),
                    JIT_RUNTIME_ABI_HASH,
                    compiled.code_bytes,
                    compiled
                        .clif_blocks
                        .map_or_else(|| "cached".to_owned(), |blocks| blocks.to_string()),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| metrics.blocks),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| metrics.values),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| metrics.instructions),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| metrics.block_parameters),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| metrics.loads),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| metrics.stores),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| { metrics.loads_per_source_instruction_milli }),
                    compiled
                        .maximum_pre_regalloc
                        .map_or(0, |metrics| { metrics.stores_per_source_instruction_milli }),
                    compiled.maximum_temporary_cache_entries.unwrap_or(0),
                    compiled.fragment_frame_slots,
                    compiled.fragment_shared_register_slots,
                    compiled.fragment_scratch_register_slots,
                    compiled.pre_regalloc_replans,
                    compiled.fast_path_hits,
                    compiled.has_control_flow,
                    compiled.plan.ir_instructions,
                    compiled.plan.php_cfg_blocks,
                    compiled.plan.estimated_clif_blocks,
                    compiled.plan.virtual_values,
                    compiled.plan.safepoint_count,
                    compiled.plan.safepoint_live_set_sum,
                    compiled.plan.fragments.len(),
                    compiled
                        .plan
                        .fragments
                        .iter()
                        .map(|fragment| fragment.blocks.len())
                        .max()
                        .unwrap_or(0),
                    compiled
                        .plan
                        .fragments
                        .iter()
                        .map(|fragment| fragment.ir_instructions)
                        .max()
                        .unwrap_or(0),
                    compiled
                        .plan
                        .fragments
                        .iter()
                        .map(|fragment| fragment.estimated_clif_blocks)
                        .max()
                        .unwrap_or(0),
                ),
                compiled.code_bytes,
                elapsed.max(1),
            )
        }
        Err(error)
            if request.compile.opt_level >= 2
                && error.code == "JIT_CRANELIFT_PRE_REGALLOC_BUDGET" =>
        {
            let mut generic_compile = request.compile.clone();
            generic_compile.opt_level = 0;
            generic_compile.region_id = format!("{}.generic", generic_compile.region_id);
            let generic_request = NativeCompileRequest {
                compile: &generic_compile,
                unit: request.unit,
                function: request.function,
                runtime_helpers: request.runtime_helpers,
            };
            let mut outcome = compile_authoritative_region(&generic_request);
            outcome.diagnostics.insert(
                0,
                format!(
                    "optimizing compile exceeded its exact backend budget and used Generic code: {error}"
                ),
            );
            if outcome.handle.is_some() {
                outcome.compile_time_nanos = start
                    .elapsed()
                    .as_nanos()
                    .try_into()
                    .unwrap_or(u64::MAX)
                    .max(1);
            }
            outcome
        }
        Err(error) => NativeCompileOutcome::skipped(
            JitCompileStatus::Rejected {
                reason: error.code.to_owned(),
            },
            format!(
                "Cranelift Generic Region IR compile rejected region `{}`: {error}",
                request.compile.region_id
            ),
        ),
    }
}

fn runtime_helper_abi_hash(_helpers: crate::JitRuntimeHelperAddresses) -> u64 {
    JIT_RUNTIME_ABI_HASH
        ^ crate::JIT_HELPER_REGISTRY_ABI_HASH
        ^ php_runtime::api::NATIVE_OPERATION_ABI_HASH
}

/// Per-lowering counters.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct CraneliftLoweringStats {
    /// Basic blocks lowered.
    pub blocks_lowered: u64,
    /// Instructions lowered.
    pub instructions_lowered: u64,
    /// Cranelift verifier ran successfully.
    pub verified: bool,
}

/// Standalone CLIF smoke result for Cranelift CLIF.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CraneliftClifSmokeResult {
    /// Stable smoke function name.
    pub function_name: &'static str,
    /// Generated Cranelift IR text.
    pub clif: String,
    /// Smoke lowering counters.
    pub stats: CraneliftLoweringStats,
}

/// Typed Cranelift lowering failure.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CraneliftLoweringError {
    /// Stable machine-readable rejection code.
    pub code: &'static str,
    /// Human-readable detail.
    pub detail: String,
    /// Minimum deterministic natural fragments required by an exact backend
    /// ceiling. Present only for pre-regalloc budget failures.
    pub required_pre_regalloc_pieces: Option<usize>,
}

impl CraneliftLoweringError {
    fn new(code: &'static str, detail: impl Into<String>) -> Self {
        Self {
            code,
            detail: detail.into(),
            required_pre_regalloc_pieces: None,
        }
    }

    fn with_required_pre_regalloc_pieces(mut self, pieces: usize) -> Self {
        self.required_pre_regalloc_pieces = Some(pieces.max(2));
        self
    }
}

impl fmt::Display for CraneliftLoweringError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.code, self.detail)
    }
}

impl std::error::Error for CraneliftLoweringError {}

/// Builds and verifies a trivial `fn(i64, i64) -> i64` add function.
///
/// This smoke intentionally does not consume PHP IR and never allocates or
/// executes native code. It exists to prove that the Cranelift frontend and
/// verifier are wired into the build in a deterministic, default-off path.
pub fn build_trivial_add_clif_smoke() -> Result<CraneliftClifSmokeResult, CraneliftLoweringError> {
    let mut signature = Signature::new(CallConv::SystemV);
    signature.params.push(AbiParam::new(types::I64));
    signature.params.push(AbiParam::new(types::I64));
    signature.returns.push(AbiParam::new(types::I64));

    let mut function = Function::with_name_signature(UserFuncName::user(0, 0), signature);
    let mut builder_context = FunctionBuilderContext::new();
    let mut stats = CraneliftLoweringStats::default();

    {
        let mut builder = FunctionBuilder::new(&mut function, &mut builder_context);
        let block = builder.create_block();
        builder.append_block_params_for_function_params(block);
        builder.switch_to_block(block);
        builder.seal_block(block);
        let params = builder.block_params(block).to_vec();
        let sum = builder.ins().iadd(params[0], params[1]);
        builder.ins().return_(&[sum]);
        builder.finalize();
    }

    let flags = settings::Flags::new(settings::builder());
    verify_function(&function, &flags).map_err(|error| {
        CraneliftLoweringError::new(
            "JIT_CRANELIFT_REJECT_VERIFIER",
            format!("Cranelift verifier rejected standalone smoke IR: {error}"),
        )
    })?;
    stats.blocks_lowered = 1;
    stats.instructions_lowered = 2;
    stats.verified = true;

    Ok(CraneliftClifSmokeResult {
        function_name: "trivial_add_i64",
        clif: function.display().to_string(),
        stats,
    })
}
fn create_region_cranelift_blocks(
    builder: &mut FunctionBuilder<'_>,
    region: &RegionGraph,
) -> Result<BTreeMap<BlockId, ir::Block>, CraneliftLoweringError> {
    let mut blocks = BTreeMap::new();
    for (index, region_block) in region.blocks.iter().enumerate() {
        if region_block.id.index() != index {
            return Err(CraneliftLoweringError::new(
                "JIT_CRANELIFT_REJECT_REGION_CONTROL_FLOW",
                format!(
                    "non-dense block id {} at position {} is outside executable Region IR",
                    region_block.id.raw(),
                    index
                ),
            ));
        }
        blocks.insert(region_block.id, builder.create_block());
    }
    Ok(blocks)
}

fn cranelift_block(
    blocks: &BTreeMap<BlockId, ir::Block>,
    block_id: BlockId,
) -> Result<ir::Block, CraneliftLoweringError> {
    blocks.get(&block_id).copied().ok_or_else(|| {
        CraneliftLoweringError::new(
            "JIT_CRANELIFT_REJECT_HELPER_CONTROL_FLOW",
            format!("target block {} is outside the lowered CFG", block_id.raw()),
        )
    })
}

#[derive(Clone, Copy, Debug)]
enum NativeLocalStorage {
    Variable(Variable),
    FrameSlot {
        frame: ir::Value,
        offset: i32,
    },
    /// Request globals are shared mutable bindings, not SSA values. The local
    /// cache remains available for continuation publication, but every PHP
    /// read observes the authoritative stable request slot directly. This
    /// keeps reference-identity changes visible across local, linked, and
    /// dynamically prepared generated calls without a post-call dispatcher.
    RequestGlobal {
        cache: NativeLocalCache,
        slot: ir::Value,
    },
}

#[derive(Clone, Copy, Debug)]
enum NativeLocalCache {
    Variable(Variable),
    FrameSlot { frame: ir::Value, offset: i32 },
}

type NativeLocalMap = BTreeMap<LocalId, NativeLocalStorage>;

/// Baseline values are materialized in compact fragment-frame slots instead
/// of frontend SSA variables. `Cached` is deliberately block-local: the
/// authoritative value has already been written to its frame slot when one
/// exists, so dropping the cache at a merge or helper boundary cannot lose
/// state. The optimizing tier continues to use Cranelift frontend variables.
#[derive(Clone, Copy, Debug)]
enum NativeRegisterStorage {
    Variable(Variable),
    FrameSlot {
        frame: ir::Value,
        offset: i32,
        type_: ir::Type,
    },
    SpillSlot {
        frame: ir::Value,
        offset: i32,
        type_: ir::Type,
    },
    Transient {
        type_: ir::Type,
    },
    Cached(ir::Value),
}

type NativeRegisterMap = BTreeMap<RegId, NativeRegisterStorage>;

fn use_region_register(
    builder: &mut FunctionBuilder<'_>,
    registers: &NativeRegisterMap,
    register: RegId,
) -> Result<ir::Value, CraneliftLoweringError> {
    match registers.get(&register).copied() {
        Some(NativeRegisterStorage::Variable(variable)) => {
            builder.try_use_var(variable).map_err(|error| {
                CraneliftLoweringError::new(
                    "JIT_CRANELIFT_REJECT_MISSING_REGISTER",
                    format!("register {} has no native value: {error}", register.raw()),
                )
            })
        }
        Some(
            NativeRegisterStorage::FrameSlot {
                frame,
                offset,
                type_,
            }
            | NativeRegisterStorage::SpillSlot {
                frame,
                offset,
                type_,
            },
        ) => {
            let value = builder
                .ins()
                .load(types::I64, MemFlagsData::new(), frame, offset);
            Ok(if type_ == types::I64 {
                value
            } else {
                builder.ins().ireduce(type_, value)
            })
        }
        Some(NativeRegisterStorage::Cached(value)) => Ok(value),
        Some(NativeRegisterStorage::Transient { .. }) | None => Err(CraneliftLoweringError::new(
            "JIT_CRANELIFT_REJECT_MISSING_REGISTER",
            format!(
                "register {} has no dominating Generic value or frame slot",
                register.raw()
            ),
        )),
    }
}

fn local_storage(
    locals: &NativeLocalMap,
    local: LocalId,
) -> Result<NativeLocalStorage, CraneliftLoweringError> {
    locals.get(&local).copied().ok_or_else(|| {
        CraneliftLoweringError::new(
            "JIT_CRANELIFT_REJECT_MISSING_LOCAL",
            format!("local {} has not been declared", local.raw()),
        )
    })
}

fn use_local_variable(
    builder: &mut FunctionBuilder<'_>,
    locals: &NativeLocalMap,
    local: LocalId,
) -> Result<ir::Value, CraneliftLoweringError> {
    match local_storage(locals, local)? {
        NativeLocalStorage::Variable(variable) => builder.try_use_var(variable).map_err(|error| {
            CraneliftLoweringError::new(
                "JIT_CRANELIFT_REJECT_MISSING_LOCAL",
                format!("local {} has no dominating value: {error}", local.raw()),
            )
        }),
        NativeLocalStorage::FrameSlot { frame, offset } => {
            Ok(builder
                .ins()
                .load(types::I64, MemFlagsData::new(), frame, offset))
        }
        NativeLocalStorage::RequestGlobal { slot, .. } => Ok(builder.ins().load(
            types::I64,
            MemFlagsData::new(),
            slot,
            std::mem::offset_of!(crate::JitNativeRequestLocalSlot, encoded) as i32,
        )),
    }
}

fn define_local_variable(
    builder: &mut FunctionBuilder<'_>,
    locals: &NativeLocalMap,
    local: LocalId,
    value: ir::Value,
) -> Result<(), CraneliftLoweringError> {
    match local_storage(locals, local)? {
        NativeLocalStorage::Variable(variable) => builder.def_var(variable, value),
        NativeLocalStorage::FrameSlot { frame, offset } => {
            builder
                .ins()
                .store(MemFlagsData::new(), value, frame, offset);
        }
        NativeLocalStorage::RequestGlobal { cache, .. } => match cache {
            NativeLocalCache::Variable(variable) => builder.def_var(variable, value),
            NativeLocalCache::FrameSlot { frame, offset } => {
                builder
                    .ins()
                    .store(MemFlagsData::new(), value, frame, offset);
            }
        },
    }
    Ok(())
}

fn lower_region_operand(
    builder: &mut FunctionBuilder<'_>,
    locals: &NativeLocalMap,
    registers: &NativeRegisterMap,
    operand: RegionOperand,
) -> Result<ir::Value, CraneliftLoweringError> {
    match operand {
        RegionOperand::Register(reg) => use_region_register(builder, registers, reg),
        RegionOperand::I64(value) => Ok(builder.ins().iconst(types::I64, value)),
        RegionOperand::Constant(constant) => Ok(builder
            .ins()
            .iconst(types::I64, crate::jit_encode_constant(constant))),
        RegionOperand::LinkedConstant { .. } => Err(CraneliftLoweringError::new(
            "JIT_CRANELIFT_LINKED_LITERAL_CONTEXT",
            "linked literal escaped its prepared compiled-call boundary",
        )),
        RegionOperand::Local(local) => use_local_variable(builder, locals, local),
    }
}

/// Resolves the one active unit view directly from the deopt/native-frame
/// record. Ordinary entries use the inline self-contained view; a linked
/// compiled call selects its callee's stable published view with one pointer
/// store and restores the preceding pointer on return.
fn lower_active_runtime_view(builder: &mut FunctionBuilder<'_>, deopt_out: ir::Value) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        deopt_out,
        std::mem::offset_of!(crate::JitDeoptState, runtime_view_pointer) as i32,
    )
}

/// Resolves the runtime view from a state that may already be a canonical
/// suspension snapshot. Live invocation state carries a non-zero selected
/// view pointer; completed side exits deliberately canonicalize that pointer
/// into the inline view before Rust stores the suspension tree.
///
/// This check is emitted only on the explicit `SUSPEND_FIBER` edge. Ordinary
/// native operations continue to consume the already-selected pointer without
/// an invocation-time validation branch.
fn lower_suspension_runtime_view(builder: &mut FunctionBuilder<'_>, state: ir::Value) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(state);
    let selected = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        state,
        std::mem::offset_of!(crate::JitDeoptState, runtime_view_pointer) as i32,
    );
    let inline = builder.ins().iadd_imm(
        state,
        i64::try_from(std::mem::offset_of!(crate::JitDeoptState, runtime_view)).unwrap_or(i64::MAX),
    );
    let has_selected = builder.ins().icmp_imm(IntCC::NotEqual, selected, 0);
    builder.ins().select(has_selected, selected, inline)
}

/// Records one baseline-native function entry in the process-owned dense
/// counter plane. This is emitted only by Generic function entry bodies:
/// optimizing code contains neither a telemetry branch nor a runtime helper.
fn lower_generic_function_entry(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    function: FunctionId,
) -> Result<(), CraneliftLoweringError> {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let view = lower_active_runtime_view(builder, deopt_out);
    let counters = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, generic_function_entry_counts) as i32,
    );
    let counters = if pointer_type == types::I64 {
        counters
    } else {
        builder.ins().ireduce(pointer_type, counters)
    };
    let byte_offset = function
        .index()
        .checked_mul(std::mem::size_of::<std::sync::atomic::AtomicU64>())
        .and_then(|offset| i64::try_from(offset).ok())
        .ok_or_else(|| {
            CraneliftLoweringError::new(
                "JIT_CRANELIFT_FUNCTION_ENTRY_COUNTER",
                "Generic function-entry counter offset does not fit the native address space",
            )
        })?;
    let counter = builder.ins().iadd_imm(counters, byte_offset);
    let one = builder.ins().iconst(types::I64, 1);
    let _ = builder.ins().atomic_rmw(
        types::I64,
        MemFlagsData::new(),
        AtomicRmwOp::Add,
        counter,
        one,
    );
    Ok(())
}

/// Bind a resolved dynamic call inside the callee's existing native entry.
///
/// The optimizing caller owns every packed slot. A successful typed check
/// replaces that owner in place; ordinary parameter initialization can then
/// borrow or retain the resulting slot exactly as it does for a static call.
/// A failed check returns before the callee frame becomes live, and the caller
/// releases the current contents of every packed slot on that status edge.
#[allow(clippy::too_many_arguments)]
fn lower_generic_bind_packed_arguments(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    argument_check: Option<NativeHelper>,
    params: &[php_ir::IrParam],
    argument_operand_offset: usize,
    arguments: ir::Value,
    result_out: ir::Value,
    deopt_out: ir::Value,
    resume_id: ir::Value,
    function: FunctionId,
) -> Result<(ir::Value, ir::Value), CraneliftLoweringError> {
    let pointer_type = builder.func.dfg.value_type(arguments);
    let weak = builder.ins().icmp_imm(
        IntCC::Equal,
        resume_id,
        i64::from(crate::JIT_NATIVE_BIND_WEAK_ENTRY_RESUME_ID),
    );
    let strict = builder.ins().icmp_imm(
        IntCC::Equal,
        resume_id,
        i64::from(crate::JIT_NATIVE_BIND_STRICT_ENTRY_RESUME_ID),
    );
    let binds_arguments = builder.ins().bor(weak, strict);
    let bind = builder.create_block();
    let ready = builder.create_block();
    builder.append_block_param(ready, pointer_type);
    builder.append_block_param(ready, types::I32);
    builder.ins().brif(
        binds_arguments,
        bind,
        &[],
        ready,
        &[arguments.into(), resume_id.into()],
    );

    builder.switch_to_block(bind);
    let typed = params.iter().any(|parameter| parameter.type_.is_some());
    let argument_check = if typed {
        Some(argument_check.ok_or_else(|| {
            CraneliftLoweringError::new(
                "JIT_CRANELIFT_NATIVE_ENTRY_BINDING",
                "typed native entry has no baseline argument-check operation",
            )
        })?)
    } else {
        None
    };
    let runtime_view = lower_active_runtime_view(builder, deopt_out);
    let function_contracts = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_function_contracts) as i32,
    );
    let function_contract = builder.ins().iadd_imm(
        function_contracts,
        i64::try_from(
            function
                .index()
                .saturating_mul(std::mem::size_of::<crate::JitNativeFunctionContractView>()),
        )
        .unwrap_or(i64::MAX),
    );
    let parameter_contracts = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        function_contract,
        std::mem::offset_of!(crate::JitNativeFunctionContractView, parameter_contracts) as i32,
    );
    let strict_value = builder.ins().iconst(types::I64, 1);
    let weak_value = builder.ins().iconst(types::I64, 0);
    let strict_value = builder.ins().select(strict, strict_value, weak_value);

    for (index, parameter) in params.iter().enumerate() {
        if parameter.type_.is_none() {
            continue;
        }
        let offset = i32::try_from(
            argument_operand_offset
                .saturating_add(index)
                .saturating_mul(8),
        )
        .map_err(|_| {
            CraneliftLoweringError::new(
                "JIT_CRANELIFT_NATIVE_ENTRY_BINDING",
                "bound parameter offset does not fit the native entry ABI",
            )
        })?;
        let original = builder
            .ins()
            .load(types::I64, MemFlagsData::new(), arguments, offset);
        let parameter_contract = builder.ins().load(
            types::I64,
            MemFlagsData::new(),
            parameter_contracts,
            i32::try_from(index.saturating_mul(8)).unwrap_or(i32::MAX),
        );
        if parameter.variadic {
            // Generated callers pass one authoritative direct array in the
            // physical variadic slot. The declared type applies to each
            // PHP-visible element, never to that compiler-owned container.
            let slot = lower_optimizing_slot_address(builder, original, deopt_out);
            let length = builder.ins().load(
                types::I64,
                MemFlagsData::new(),
                slot,
                std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
            );
            let entries = builder.ins().load(
                pointer_type,
                MemFlagsData::new(),
                slot,
                std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
            );
            let scan = builder.create_block();
            let inspect = builder.create_block();
            let complete = builder.create_block();
            builder.append_block_param(scan, types::I64);
            let zero = builder.ins().iconst(types::I64, 0);
            builder.ins().jump(scan, &[zero.into()]);

            builder.switch_to_block(scan);
            let element_index = builder.block_params(scan)[0];
            let done = builder
                .ins()
                .icmp(IntCC::UnsignedGreaterThanOrEqual, element_index, length);
            builder.ins().brif(done, complete, &[], inspect, &[]);

            builder.switch_to_block(inspect);
            let entry_offset = builder.ins().imul_imm(
                element_index,
                i64::try_from(std::mem::size_of::<crate::JitNativeDirectArrayEntry>())
                    .unwrap_or(i64::MAX),
            );
            let entry = builder.ins().iadd(entries, entry_offset);
            let value_field = builder.ins().iadd_imm(
                entry,
                i64::try_from(std::mem::offset_of!(
                    crate::JitNativeDirectArrayEntry,
                    value
                ))
                .unwrap_or(i64::MAX),
            );
            let element = builder
                .ins()
                .load(types::I64, MemFlagsData::new(), value_field, 0);
            let call = call_native_helper(
                module,
                builder,
                argument_check.expect("typed variadic entry checker"),
                &[element, parameter_contract, strict_value, result_out],
            );
            let status = builder.inst_results(call)[0];
            let admitted = builder.create_block();
            let failed = builder.create_block();
            let ok = builder.ins().icmp_imm(IntCC::Equal, status, 0);
            builder.ins().brif(ok, admitted, &[], failed, &[]);

            builder.switch_to_block(failed);
            return_native_or_fragment_control(builder, status, result_out);

            builder.switch_to_block(admitted);
            let checked = builder
                .ins()
                .load(types::I64, MemFlagsData::new(), result_out, 0);
            if !parameter.by_ref {
                lower_optimizing_release_replaced_call_owner(builder, element, checked, deopt_out);
            }
            builder
                .ins()
                .store(MemFlagsData::new(), checked, value_field, 0);
            let next = builder.ins().iadd_imm(element_index, 1);
            builder.ins().jump(scan, &[next.into()]);

            builder.switch_to_block(complete);
            continue;
        }
        let parameter_ready = builder.create_block();
        if parameter.by_ref {
            let payload = lower_direct_reference_payload_unchecked(builder, original, deopt_out);
            if let Some(native_match) = lower_optimizing_type_guard(
                builder,
                payload,
                parameter
                    .type_
                    .as_ref()
                    .expect("typed packed parameter retains its type"),
                deopt_out,
            ) {
                let cold_check = builder.create_block();
                let reference =
                    lower_value_has_tag(builder, original, crate::JIT_VALUE_RUNTIME_REFERENCE_TAG);
                let native_match = builder.ins().band(reference, native_match);
                builder
                    .ins()
                    .brif(native_match, parameter_ready, &[], cold_check, &[]);
                builder.switch_to_block(cold_check);
            }
        }
        let call = call_native_helper(
            module,
            builder,
            argument_check.expect("typed entry checker"),
            &[original, parameter_contract, strict_value, result_out],
        );
        let status = builder.inst_results(call)[0];
        let checked = builder
            .ins()
            .load(types::I64, MemFlagsData::new(), result_out, 0);
        let admitted = builder.create_block();
        let failed = builder.create_block();
        let ok = builder.ins().icmp_imm(IntCC::Equal, status, 0);
        builder.ins().brif(ok, admitted, &[], failed, &[]);

        builder.switch_to_block(failed);
        return_native_or_fragment_control(builder, status, result_out);

        builder.switch_to_block(admitted);
        // The source SSA/local owner remains live in the caller. The packed
        // owner is therefore known to be shared and can be decremented in
        // direct CLIF before the checked owner replaces it.
        lower_optimizing_release_replaced_call_owner(builder, original, checked, deopt_out);
        builder
            .ins()
            .store(MemFlagsData::new(), checked, arguments, offset);
        builder.ins().jump(parameter_ready, &[]);
        builder.switch_to_block(parameter_ready);
    }
    let normal_entry = builder.ins().iconst(types::I32, -1);
    builder
        .ins()
        .jump(ready, &[arguments.into(), normal_entry.into()]);

    builder.switch_to_block(ready);
    Ok((
        builder.block_params(ready)[0],
        builder.block_params(ready)[1],
    ))
}

#[derive(Clone, Copy)]
struct NativeCallTracePublication {
    arguments_field: ir::Value,
    count_field: ir::Value,
    fixed_count_field: ir::Value,
    fixed_arguments_field: ir::Value,
    tail_arguments_field: ir::Value,
    previous_arguments: ir::Value,
    previous_count: ir::Value,
    previous_fixed_count: ir::Value,
    previous_fixed_arguments: ir::Value,
    previous_tail_arguments: ir::Value,
    trace_depth_field: ir::Value,
    previous_trace_depth: ir::Value,
}

fn lower_native_function_trace_metadata(
    builder: &mut FunctionBuilder<'_>,
    pointer_type: ir::Type,
    runtime_view: ir::Value,
    function: ir::Value,
) -> ir::Value {
    let contracts = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_function_contracts) as i32,
    );
    let function = if builder.func.dfg.value_type(function) == pointer_type {
        function
    } else {
        builder.ins().uextend(pointer_type, function)
    };
    let offset = builder.ins().imul_imm(
        function,
        i64::try_from(std::mem::size_of::<crate::JitNativeFunctionContractView>())
            .unwrap_or(i64::MAX),
    );
    let contract = builder.ins().iadd(contracts, offset);
    builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        contract,
        std::mem::offset_of!(crate::JitNativeFunctionContractView, trace_metadata) as i32,
    )
}

#[allow(clippy::too_many_arguments)]
fn publish_native_shadow_frame(
    builder: &mut FunctionBuilder<'_>,
    pointer_type: ir::Type,
    runtime: ir::Value,
    metadata: ir::Value,
    arguments: ir::Value,
    argument_count: ir::Value,
    fixed_argument_count: ir::Value,
    tail_arguments: ir::Value,
) -> (ir::Value, ir::Value) {
    let frames = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime,
        std::mem::offset_of!(crate::JitNativeFastStateHeader, trace_frames) as i32,
    );
    let depth_field = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime,
        std::mem::offset_of!(crate::JitNativeFastStateHeader, trace_depth) as i32,
    );
    let depth = builder
        .ins()
        .load(types::I32, MemFlagsData::new(), depth_field, 0);
    let depth_wide = builder.ins().uextend(pointer_type, depth);
    // Recursion is bounded by the frame arena, not by this buffer, so the
    // depth can exceed the published shadow stack. Writing at that depth
    // overruns the request-owned mapping. Clamp to the last slot instead: the
    // deepest frames stop being individually addressable once the stack is
    // full, which only truncates a backtrace, while the arena keeps owning
    // the actual recursion limit.
    let capacity = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        runtime,
        std::mem::offset_of!(crate::JitNativeFastStateHeader, trace_capacity) as i32,
    );
    let capacity_wide = builder.ins().uextend(pointer_type, capacity);
    let last_slot = builder.ins().iadd_imm(capacity_wide, -1);
    let bounded = builder.ins().umin(depth_wide, last_slot);
    let empty = builder.ins().icmp_imm(IntCC::Equal, capacity_wide, 0);
    let zero = builder.ins().iconst(pointer_type, 0);
    let bounded = builder.ins().select(empty, zero, bounded);
    let offset = builder.ins().imul_imm(
        bounded,
        i64::try_from(std::mem::size_of::<crate::JitNativeTraceFrame>()).unwrap_or(i64::MAX),
    );
    let frame = builder.ins().iadd(frames, offset);
    for (value, offset) in [
        (
            metadata,
            std::mem::offset_of!(crate::JitNativeTraceFrame, metadata),
        ),
        (
            arguments,
            std::mem::offset_of!(crate::JitNativeTraceFrame, arguments),
        ),
    ] {
        builder
            .ins()
            .store(MemFlagsData::new(), value, frame, offset as i32);
    }
    for (value, offset) in [
        (
            argument_count,
            std::mem::offset_of!(crate::JitNativeTraceFrame, argument_count),
        ),
        (
            fixed_argument_count,
            std::mem::offset_of!(crate::JitNativeTraceFrame, fixed_argument_count),
        ),
    ] {
        builder
            .ins()
            .store(MemFlagsData::new(), value, frame, offset as i32);
    }
    let zero_pointer = builder.ins().iconst(pointer_type, 0);
    builder.ins().store(
        MemFlagsData::new(),
        zero_pointer,
        frame,
        std::mem::offset_of!(crate::JitNativeTraceFrame, fixed_arguments) as i32,
    );
    builder.ins().store(
        MemFlagsData::new(),
        tail_arguments,
        frame,
        std::mem::offset_of!(crate::JitNativeTraceFrame, tail_arguments) as i32,
    );
    let zero64 = builder.ins().iconst(types::I64, 0);
    for offset in [
        std::mem::offset_of!(crate::JitNativeTraceFrame, receiver),
        std::mem::offset_of!(crate::JitNativeTraceFrame, class_bytes),
    ] {
        builder
            .ins()
            .store(MemFlagsData::new(), zero64, frame, offset as i32);
    }
    let zero32 = builder.ins().iconst(types::I32, 0);
    for offset in [
        std::mem::offset_of!(crate::JitNativeTraceFrame, class_length),
        std::mem::offset_of!(crate::JitNativeTraceFrame, flags),
    ] {
        builder
            .ins()
            .store(MemFlagsData::new(), zero32, frame, offset as i32);
    }
    let next = builder.ins().iadd_imm(depth, 1);
    builder
        .ins()
        .store(MemFlagsData::new(), next, depth_field, 0);
    (depth_field, depth)
}

fn publish_native_call_trace(
    builder: &mut FunctionBuilder<'_>,
    pointer_type: ir::Type,
    runtime: ir::Value,
    runtime_view: ir::Value,
    trace_metadata: ir::Value,
    values: &[ir::Value],
    fixed_count: usize,
    tail: Option<(ir::Value, ir::Value)>,
) -> Result<NativeCallTracePublication, CraneliftLoweringError> {
    let trace_size = u32::try_from(values.len().max(1).saturating_mul(8)).map_err(|_| {
        CraneliftLoweringError::new(
            "JIT_CRANELIFT_NATIVE_TRACE_ARGUMENT",
            "native trace argument storage exceeds the stack-slot ABI",
        )
    })?;
    let trace = allocate_native_stack_storage(builder, pointer_type, trace_size, 3);
    for (index, value) in values.iter().copied().enumerate() {
        builder.ins().store(
            MemFlagsData::new(),
            value,
            trace,
            i32::try_from(index.saturating_mul(8)).unwrap_or(i32::MAX),
        );
    }
    let arguments_field = builder.ins().iadd_imm(
        runtime_view,
        i64::try_from(std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            active_call_arguments,
        ))
        .unwrap_or(i64::MAX),
    );
    let count_field = builder.ins().iadd_imm(
        runtime_view,
        i64::try_from(std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            active_call_argument_count,
        ))
        .unwrap_or(i64::MAX),
    );
    let fixed_count_field = builder.ins().iadd_imm(
        runtime_view,
        i64::try_from(std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            active_call_fixed_argument_count,
        ))
        .unwrap_or(i64::MAX),
    );
    let fixed_arguments_field = builder.ins().iadd_imm(
        runtime_view,
        i64::try_from(std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            active_call_fixed_arguments,
        ))
        .unwrap_or(i64::MAX),
    );
    let tail_arguments_field = builder.ins().iadd_imm(
        runtime_view,
        i64::try_from(std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            active_call_tail_arguments,
        ))
        .unwrap_or(i64::MAX),
    );
    let count = if let Some((count, _)) = tail {
        builder.ins().ireduce(types::I32, count)
    } else {
        builder
            .ins()
            .iconst(types::I32, i64::try_from(values.len()).unwrap_or(i64::MAX))
    };
    let fixed_count = builder
        .ins()
        .iconst(types::I32, i64::try_from(fixed_count).unwrap_or(i64::MAX));
    let tail_arguments = if let Some((_, array)) = tail {
        array
    } else {
        builder.ins().iconst(types::I64, 0)
    };
    let (trace_depth_field, previous_trace_depth) = publish_native_shadow_frame(
        builder,
        pointer_type,
        runtime,
        trace_metadata,
        trace,
        count,
        fixed_count,
        tail_arguments,
    );
    let publication = NativeCallTracePublication {
        arguments_field,
        count_field,
        fixed_count_field,
        fixed_arguments_field,
        tail_arguments_field,
        previous_arguments: builder.ins().load(
            pointer_type,
            MemFlagsData::new(),
            arguments_field,
            0,
        ),
        previous_count: builder
            .ins()
            .load(types::I32, MemFlagsData::new(), count_field, 0),
        previous_fixed_count: builder.ins().load(
            types::I32,
            MemFlagsData::new(),
            fixed_count_field,
            0,
        ),
        previous_fixed_arguments: builder.ins().load(
            pointer_type,
            MemFlagsData::new(),
            fixed_arguments_field,
            0,
        ),
        previous_tail_arguments: builder.ins().load(
            types::I64,
            MemFlagsData::new(),
            tail_arguments_field,
            0,
        ),
        trace_depth_field,
        previous_trace_depth,
    };
    builder
        .ins()
        .store(MemFlagsData::new(), trace, arguments_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), count, count_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), fixed_count, fixed_count_field, 0);
    let zero = builder.ins().iconst(pointer_type, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), zero, fixed_arguments_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), tail_arguments, tail_arguments_field, 0);
    Ok(publication)
}

fn restore_native_call_trace(
    builder: &mut FunctionBuilder<'_>,
    publication: NativeCallTracePublication,
) {
    builder.ins().store(
        MemFlagsData::new(),
        publication.previous_arguments,
        publication.arguments_field,
        0,
    );
    builder.ins().store(
        MemFlagsData::new(),
        publication.previous_count,
        publication.count_field,
        0,
    );
    builder.ins().store(
        MemFlagsData::new(),
        publication.previous_fixed_count,
        publication.fixed_count_field,
        0,
    );
    builder.ins().store(
        MemFlagsData::new(),
        publication.previous_fixed_arguments,
        publication.fixed_arguments_field,
        0,
    );
    builder.ins().store(
        MemFlagsData::new(),
        publication.previous_tail_arguments,
        publication.tail_arguments_field,
        0,
    );
    builder.ins().store(
        MemFlagsData::new(),
        publication.previous_trace_depth,
        publication.trace_depth_field,
        0,
    );
}

fn publish_native_packed_call_trace(
    builder: &mut FunctionBuilder<'_>,
    pointer_type: ir::Type,
    runtime: ir::Value,
    runtime_view: ir::Value,
    trace_metadata: ir::Value,
    packed: ir::Value,
    count: ir::Value,
) -> NativeCallTracePublication {
    let field = |builder: &mut FunctionBuilder<'_>, offset: usize| {
        builder
            .ins()
            .iadd_imm(runtime_view, i64::try_from(offset).unwrap_or(i64::MAX))
    };
    let arguments_field = field(
        builder,
        std::mem::offset_of!(crate::JitNativeRuntimeView, active_call_arguments),
    );
    let count_field = field(
        builder,
        std::mem::offset_of!(crate::JitNativeRuntimeView, active_call_argument_count),
    );
    let fixed_count_field = field(
        builder,
        std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            active_call_fixed_argument_count
        ),
    );
    let fixed_arguments_field = field(
        builder,
        std::mem::offset_of!(crate::JitNativeRuntimeView, active_call_fixed_arguments),
    );
    let tail_arguments_field = field(
        builder,
        std::mem::offset_of!(crate::JitNativeRuntimeView, active_call_tail_arguments),
    );
    let count = builder.ins().ireduce(types::I32, count);
    let no_tail = builder.ins().iconst(types::I64, 0);
    let (trace_depth_field, previous_trace_depth) = publish_native_shadow_frame(
        builder,
        pointer_type,
        runtime,
        trace_metadata,
        packed,
        count,
        count,
        no_tail,
    );
    let publication = NativeCallTracePublication {
        arguments_field,
        count_field,
        fixed_count_field,
        fixed_arguments_field,
        tail_arguments_field,
        previous_arguments: builder.ins().load(
            pointer_type,
            MemFlagsData::new(),
            arguments_field,
            0,
        ),
        previous_count: builder
            .ins()
            .load(types::I32, MemFlagsData::new(), count_field, 0),
        previous_fixed_count: builder.ins().load(
            types::I32,
            MemFlagsData::new(),
            fixed_count_field,
            0,
        ),
        previous_fixed_arguments: builder.ins().load(
            pointer_type,
            MemFlagsData::new(),
            fixed_arguments_field,
            0,
        ),
        previous_tail_arguments: builder.ins().load(
            types::I64,
            MemFlagsData::new(),
            tail_arguments_field,
            0,
        ),
        trace_depth_field,
        previous_trace_depth,
    };
    builder
        .ins()
        .store(MemFlagsData::new(), packed, arguments_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), count, count_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), count, fixed_count_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), packed, fixed_arguments_field, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), no_tail, tail_arguments_field, 0);
    publication
}

fn lower_linked_native_literal_value(
    builder: &mut FunctionBuilder<'_>,
    link_index: u32,
    constant_index: u32,
    deopt_out: ir::Value,
) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let caller_view = lower_active_runtime_view(builder, deopt_out);
    let links = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        caller_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_linked_functions) as i32,
    );
    let link = builder.ins().iadd_imm(
        links,
        i64::from(link_index)
            * i64::try_from(std::mem::size_of::<crate::JitNativeLinkedFunction>())
                .unwrap_or(i64::MAX),
    );
    let callee_view = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        link,
        std::mem::offset_of!(crate::JitNativeLinkedFunction, runtime_view) as i32,
    );
    let literals = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        callee_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_literal_slots) as i32,
    );
    let literal = builder.ins().iadd_imm(
        literals,
        i64::from(constant_index)
            * i64::try_from(std::mem::size_of::<crate::JitNativeTrustedLiteralSlot>())
                .unwrap_or(i64::MAX),
    );
    builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        literal,
        std::mem::offset_of!(crate::JitNativeTrustedLiteralSlot, value) as i32,
    )
}

fn native_integer_fits_immediate(value: i64) -> bool {
    crate::jit_decode_runtime_value(value).is_none() && crate::jit_decode_constant(value).is_none()
}

fn constant_requires_native_storage(constants: &[IrConstant], index: u32) -> bool {
    match constants.get(index as usize) {
        Some(IrConstant::Int(value)) => !native_integer_fits_immediate(*value),
        Some(
            IrConstant::Float(_)
            | IrConstant::String(_)
            | IrConstant::StringBytes(_)
            | IrConstant::Array(_),
        ) => true,
        Some(
            IrConstant::Null
            | IrConstant::Bool(_)
            | IrConstant::NamedConstant(_)
            | IrConstant::ClassConstant { .. },
        )
        | None => false,
    }
}

fn prepared_call_operand_is_constant(operand: RegionOperand) -> bool {
    matches!(
        operand,
        RegionOperand::Constant(_) | RegionOperand::LinkedConstant { .. } | RegionOperand::I64(_)
    )
}

fn prepared_call_integer_constant(
    constants: &[IrConstant],
    value_flow: &ExecutableValueFlow,
    operand: RegionOperand,
) -> Option<i64> {
    match operand {
        RegionOperand::I64(value) => Some(value),
        RegionOperand::Constant(index)
        | RegionOperand::LinkedConstant {
            constant: index, ..
        } => match constants.get(index as usize) {
            Some(IrConstant::Int(value)) => Some(*value),
            _ => None,
        },
        RegionOperand::Register(_) | RegionOperand::Local(_) => value_flow
            .operand_fact(constants, operand)
            .integer_range
            .filter(|range| range.minimum == range.maximum)
            .map(|range| range.minimum),
    }
}

fn prepared_call_operand_is_null(operand: RegionOperand) -> bool {
    matches!(operand, RegionOperand::Constant(index) if index == u32::MAX)
}

fn optimizing_fact_may_be_reference(fact: SsaValueFact) -> bool {
    fact.certainty == crate::region_ir::SsaCertainty::Unknown
        || matches!(
            fact.class,
            SsaValueClass::ReferenceHandle | SsaValueClass::MixedHandle
        )
}

/// Publication-owned scalar result conversion for an optimizing return.
///
/// Every variant is a total native encoding operation.  In particular this
/// does not describe a runtime type test: values whose conversion cannot be
/// proved while publishing the artifact never enter the optimizing region.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NativeOptimizingReturnPlan {
    Immediate(i64),
    DirectInt(i64),
    DirectFloat(u64),
    IntToFloat,
}

impl NativeOptimizingReturnPlan {
    const fn value_allocations(self) -> usize {
        match self {
            Self::Immediate(_) => 0,
            Self::DirectInt(_) | Self::DirectFloat(_) | Self::IntToFloat => 1,
        }
    }
}

fn lower_prepared_native_call_operand(
    builder: &mut FunctionBuilder<'_>,
    locals: &NativeLocalMap,
    registers: &NativeRegisterMap,
    constants: &[IrConstant],
    operand: RegionOperand,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    if let RegionOperand::LinkedConstant {
        link_index,
        constant,
        ..
    } = operand
    {
        return Ok(lower_linked_native_literal_value(
            builder,
            link_index,
            constant,
            transition.deopt_out,
        ));
    }
    let RegionOperand::Constant(constant) = operand else {
        return lower_region_operand(builder, locals, registers, operand);
    };
    let value = match constants.get(constant as usize) {
        Some(IrConstant::Null) => crate::jit_encode_constant(u32::MAX),
        Some(IrConstant::Bool(false)) => crate::jit_encode_constant(crate::JIT_VALUE_FALSE),
        Some(IrConstant::Bool(true)) => crate::jit_encode_constant(crate::JIT_VALUE_TRUE),
        Some(IrConstant::Int(value)) if native_integer_fits_immediate(*value) => *value,
        // A namespace-colliding integer is published in the trusted literal
        // slot for this IR constant. Keep the producer's constant index here;
        // using the integer bits themselves would decode the collision as an
        // unrelated literal-table index.
        Some(IrConstant::Int(_)) => crate::jit_encode_constant(constant),
        _ => crate::jit_encode_constant(constant),
    };
    let value = builder.ins().iconst(types::I64, value);
    if constant_requires_native_storage(constants, constant) {
        Ok(lower_native_literal_value(builder, value, constant, transition.deopt_out).0)
    } else {
        Ok(value)
    }
}

fn lower_ir_operand(
    builder: &mut FunctionBuilder<'_>,
    locals: &NativeLocalMap,
    registers: &NativeRegisterMap,
    operand: php_ir::Operand,
) -> Result<ir::Value, CraneliftLoweringError> {
    match operand {
        php_ir::Operand::Register(register) => use_region_register(builder, registers, register),
        php_ir::Operand::Local(local) => use_local_variable(builder, locals, local),
        php_ir::Operand::Constant(constant) => Ok(builder
            .ins()
            .iconst(types::I64, crate::jit_encode_constant(constant.raw()))),
    }
}

fn define_region_register(
    builder: &mut FunctionBuilder<'_>,
    register_variables: &NativeRegisterMap,
    registers: &mut NativeRegisterMap,
    register: RegId,
    value: ir::Value,
) -> Result<(), CraneliftLoweringError> {
    let storage = register_variables.get(&register).copied().ok_or_else(|| {
        CraneliftLoweringError::new(
            "JIT_CRANELIFT_REJECT_MISSING_REGISTER",
            format!("register {} has no declared native storage", register.raw()),
        )
    })?;
    match storage {
        NativeRegisterStorage::Variable(variable) => {
            builder.def_var(variable, value);
            registers.insert(register, NativeRegisterStorage::Variable(variable));
        }
        NativeRegisterStorage::FrameSlot {
            frame,
            offset,
            type_,
        } => {
            let stored = if type_ == types::I64 {
                value
            } else {
                builder.ins().uextend(types::I64, value)
            };
            builder
                .ins()
                .store(MemFlagsData::new(), stored, frame, offset);
            registers.insert(register, NativeRegisterStorage::Cached(value));
        }
        NativeRegisterStorage::SpillSlot {
            frame,
            offset,
            type_,
        } => {
            let stored = if type_ == types::I64 {
                value
            } else {
                builder.ins().uextend(types::I64, value)
            };
            builder
                .ins()
                .store(MemFlagsData::new(), stored, frame, offset);
            registers.insert(
                register,
                NativeRegisterStorage::SpillSlot {
                    frame,
                    offset,
                    type_,
                },
            );
        }
        NativeRegisterStorage::Transient { type_ } => {
            debug_assert_eq!(builder.func.dfg.value_type(value), type_);
            registers.insert(register, NativeRegisterStorage::Cached(value));
        }
        NativeRegisterStorage::Cached(_) => {
            return Err(CraneliftLoweringError::new(
                "JIT_CRANELIFT_REJECT_REGISTER_STORAGE",
                format!("register {} declaration is already cached", register.raw()),
            ));
        }
    }
    Ok(())
}

fn require_native_operation_ok(
    builder: &mut FunctionBuilder<'_>,
    status: ir::Value,
    terminal_exit: NativeTerminalExit,
) -> Result<(), CraneliftLoweringError> {
    let ok = builder.create_block();
    let is_ok = builder.ins().icmp_imm(IntCC::Equal, status, 0);
    let empty = builder.ins().iconst(types::I64, 0);
    builder.ins().brif(
        is_ok,
        ok,
        &[],
        terminal_exit.block,
        &[status.into(), empty.into()],
    );
    builder.switch_to_block(ok);
    Ok(())
}

fn allocate_native_frame_storage(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    frame_alloc: Option<NativeHelper>,
    bytes: u32,
    alignment_log2: u8,
    _result_out: ir::Value,
) -> ir::Value {
    let pointer_type = module.target_config().pointer_type();
    let Some(helper) = frame_alloc else {
        let slot = builder.create_sized_stack_slot(StackSlotData::new(
            StackSlotKind::ExplicitSlot,
            bytes,
            alignment_log2,
        ));
        return builder.ins().stack_addr(pointer_type, slot, 0);
    };
    let context = builder.ins().iconst(types::I64, 0);
    let bytes = builder.ins().iconst(types::I64, i64::from(bytes));
    let alignment = builder.ins().iconst(types::I64, 1_i64 << alignment_log2);
    let call = call_native_helper(module, builder, helper, &[context, bytes, alignment]);
    let pointer = builder.inst_results(call)[0];
    let allocated = builder.create_block();
    let non_null = builder.ins().icmp_imm(IntCC::NotEqual, pointer, 0);
    let empty = builder.ins().iconst(types::I64, 0);
    let status = builder
        .ins()
        .iconst(types::I32, i64::from(crate::JitCallStatus::RUNTIME_ERROR.0));
    let terminal_exit = helper
        .terminal_exit
        .expect("function-local frame allocator must have a terminal exit");
    builder.ins().brif(
        non_null,
        allocated,
        &[],
        terminal_exit.block,
        &[status.into(), empty.into()],
    );
    builder.switch_to_block(allocated);
    pointer
}

fn allocate_native_stack_storage(
    builder: &mut FunctionBuilder<'_>,
    pointer_type: ir::Type,
    bytes: u32,
    alignment_log2: u8,
) -> ir::Value {
    let slot = builder.create_sized_stack_slot(StackSlotData::new(
        StackSlotKind::ExplicitSlot,
        bytes,
        alignment_log2,
    ));
    builder.ins().stack_addr(pointer_type, slot, 0)
}

fn release_native_frame_storage(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    frame_release: Option<NativeHelper>,
    pointer: ir::Value,
    _result_out: ir::Value,
) -> Result<(), CraneliftLoweringError> {
    let Some(helper) = frame_release else {
        return Ok(());
    };
    let context = builder.ins().iconst(types::I64, 0);
    let call = call_native_helper(module, builder, helper, &[context, pointer]);
    require_native_operation_ok(
        builder,
        builder.inst_results(call)[0],
        helper.terminal_exit()?,
    )
}

fn native_local_mask_words(live_locals: &[LocalId]) -> [u64; crate::JIT_DEOPT_LOCAL_MASK_WORDS] {
    let mut masks = [0_u64; crate::JIT_DEOPT_LOCAL_MASK_WORDS];
    for local in live_locals {
        let index = local.index();
        if index < crate::JIT_DEOPT_MAX_SLOTS {
            masks[index / u64::BITS as usize] |= 1_u64 << (index % u64::BITS as usize);
        }
    }
    masks
}

fn publish_native_local_masks(
    builder: &mut FunctionBuilder<'_>,
    state_out: ir::Value,
    live_locals: &[LocalId],
) {
    let masks = native_local_mask_words(live_locals);
    let initialized = builder.ins().iconst(types::I64, masks[0] as i64);
    builder.ins().store(
        MemFlagsData::new(),
        initialized,
        state_out,
        std::mem::offset_of!(crate::JitDeoptState, initialized_mask) as i32,
    );
    let high_base = std::mem::offset_of!(crate::JitDeoptState, initialized_masks_high);
    for (index, mask) in masks[1..].iter().enumerate() {
        let initialized = builder.ins().iconst(types::I64, *mask as i64);
        builder.ins().store(
            MemFlagsData::new(),
            initialized,
            state_out,
            high_base.saturating_add(index.saturating_mul(8)) as i32,
        );
    }
}

#[derive(Clone, Copy)]
enum NativeLocalCopyDirection {
    FrameToState,
    StateToFrame,
}

fn copy_native_local_state_values(
    builder: &mut FunctionBuilder<'_>,
    state: ir::Value,
    locals: &NativeLocalMap,
    live_locals: &[LocalId],
    direction: NativeLocalCopyDirection,
) -> Result<bool, CraneliftLoweringError> {
    let mut slots = Vec::with_capacity(live_locals.len());
    let mut frame = None;
    for local in live_locals {
        let NativeLocalStorage::FrameSlot {
            frame: local_frame,
            offset: frame_offset,
        } = local_storage(locals, *local)?
        else {
            return Ok(false);
        };
        if frame.is_some_and(|frame| frame != local_frame) {
            return Ok(false);
        }
        frame = Some(local_frame);
        let state_offset = std::mem::offset_of!(crate::JitDeoptState, slots)
            .saturating_add(local.index().saturating_mul(8));
        slots.push((frame_offset, state_offset as i32));
    }
    let Some(frame) = frame else {
        return Ok(true);
    };

    let mut start = 0;
    while start < slots.len() {
        let mut end = start + 1;
        while end < slots.len()
            && slots[end].0 == slots[end - 1].0.saturating_add(8)
            && slots[end].1 == slots[end - 1].1.saturating_add(8)
        {
            end += 1;
        }
        let (frame_base, state_base) = slots[start];
        let mut byte_offset = 0_i32;
        let mut bytes = (end - start).saturating_mul(8);
        while bytes >= 16 {
            let (source, source_offset, destination, destination_offset) = match direction {
                NativeLocalCopyDirection::FrameToState => (frame, frame_base, state, state_base),
                NativeLocalCopyDirection::StateToFrame => (state, state_base, frame, frame_base),
            };
            let value = builder.ins().load(
                types::I8X16,
                MemFlagsData::new(),
                source,
                source_offset.saturating_add(byte_offset),
            );
            builder.ins().store(
                MemFlagsData::new(),
                value,
                destination,
                destination_offset.saturating_add(byte_offset),
            );
            byte_offset = byte_offset.saturating_add(16);
            bytes -= 16;
        }
        if bytes == 8 {
            let (source, source_offset, destination, destination_offset) = match direction {
                NativeLocalCopyDirection::FrameToState => (frame, frame_base, state, state_base),
                NativeLocalCopyDirection::StateToFrame => (state, state_base, frame, frame_base),
            };
            let value = builder.ins().load(
                types::I64,
                MemFlagsData::new(),
                source,
                source_offset.saturating_add(byte_offset),
            );
            builder.ins().store(
                MemFlagsData::new(),
                value,
                destination,
                destination_offset.saturating_add(byte_offset),
            );
        }
        start = end;
    }
    Ok(true)
}

fn restore_native_local_state_values(
    builder: &mut FunctionBuilder<'_>,
    state: ir::Value,
    locals: &NativeLocalMap,
    live_locals: &[LocalId],
) -> Result<(), CraneliftLoweringError> {
    if copy_native_local_state_values(
        builder,
        state,
        locals,
        live_locals,
        NativeLocalCopyDirection::StateToFrame,
    )? {
        return Ok(());
    }
    for local in live_locals {
        let offset = std::mem::offset_of!(crate::JitDeoptState, slots)
            .saturating_add(local.index().saturating_mul(8));
        let value = builder
            .ins()
            .load(types::I64, MemFlagsData::new(), state, offset as i32);
        define_local_variable(builder, locals, *local, value)?;
    }
    Ok(())
}

fn publish_native_call_state(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    function: FunctionId,
    local_count: u32,
    instruction: &RegionInstruction,
    locals: &NativeLocalMap,
    native_version: u32,
) -> Result<(), CraneliftLoweringError> {
    publish_native_continuation_state(
        builder,
        deopt_out,
        function,
        local_count,
        instruction.continuation_id,
        &instruction.live_locals,
        locals,
        native_version,
    )
}

fn copy_native_deopt_state(
    builder: &mut FunctionBuilder<'_>,
    pointer_type: ir::Type,
    destination: ir::Value,
    source: ir::Value,
) {
    let state_bytes = std::mem::size_of::<crate::JitDeoptState>();
    debug_assert_eq!(state_bytes % std::mem::size_of::<u64>(), 0);
    let copy_loop = builder.create_block();
    let copy_word = builder.create_block();
    let copy_done = builder.create_block();
    builder.append_block_param(copy_loop, pointer_type);
    let start = builder.ins().iconst(pointer_type, 0);
    builder.ins().jump(copy_loop, &[start.into()]);

    builder.switch_to_block(copy_loop);
    let byte_offset = builder.block_params(copy_loop)[0];
    let remains = builder.ins().icmp_imm(
        IntCC::UnsignedLessThan,
        byte_offset,
        i64::try_from(state_bytes).unwrap_or(i64::MAX),
    );
    builder.ins().brif(remains, copy_word, &[], copy_done, &[]);

    builder.switch_to_block(copy_word);
    let source = builder.ins().iadd(source, byte_offset);
    let target = builder.ins().iadd(destination, byte_offset);
    let word = builder
        .ins()
        .load(types::I64, MemFlagsData::new(), source, 0);
    builder.ins().store(MemFlagsData::new(), word, target, 0);
    let next_offset = builder.ins().iadd_imm(byte_offset, 8);
    builder.ins().jump(copy_loop, &[next_offset.into()]);

    builder.switch_to_block(copy_done);
}

/// Saves the callee continuation before a compiled caller overwrites the
/// shared state buffer with its own `NativeCall` continuation. This executes
/// only on the explicit `SUSPEND_FIBER` side exit and writes directly into the
/// request-owned demand-backed suspension stack published in the fast state.
fn capture_native_fiber_callee_if_suspended(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    status: ir::Value,
    deopt_out: ir::Value,
    result_out: ir::Value,
) -> ir::Value {
    let capture = builder.create_block();
    let unchanged = builder.create_block();
    let ready = builder.create_block();
    builder.append_block_param(ready, types::I64);
    let suspended = builder.ins().icmp_imm(
        IntCC::Equal,
        status,
        i64::from(crate::JitCallStatus::SUSPEND_FIBER.0),
    );
    builder.ins().brif(suspended, capture, &[], unchanged, &[]);

    builder.switch_to_block(unchanged);
    let no_link = builder.ins().iconst(types::I64, 0);
    builder.ins().jump(ready, &[no_link.into()]);

    builder.switch_to_block(capture);
    let pointer_type = module.target_config().pointer_type();
    let view = lower_suspension_runtime_view(builder, deopt_out);
    let states = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, fiber_suspension_states) as i32,
    );
    let next_pointer = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, fiber_suspension_next) as i32,
    );
    let capacity = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, fiber_suspension_capacity) as i32,
    );
    let index = builder
        .ins()
        .load(types::I32, MemFlagsData::new(), next_pointer, 0);
    let available = builder.create_block();
    let exhausted = builder.create_block();
    let within_capacity = builder.ins().icmp(IntCC::UnsignedLessThan, index, capacity);
    builder
        .ins()
        .brif(within_capacity, available, &[], exhausted, &[]);

    builder.switch_to_block(exhausted);
    let empty = builder.ins().iconst(types::I64, 0);
    builder
        .ins()
        .store(MemFlagsData::new(), empty, result_out, 0);
    let runtime_error = builder
        .ins()
        .iconst(types::I32, i64::from(crate::JitCallStatus::RUNTIME_ERROR.0));
    return_native_or_fragment_control(builder, runtime_error, result_out);

    builder.switch_to_block(available);
    let index_pointer = builder.ins().uextend(pointer_type, index);
    let offset = builder.ins().imul_imm(
        index_pointer,
        i64::try_from(std::mem::size_of::<crate::JitDeoptState>()).unwrap_or(i64::MAX),
    );
    let destination = builder.ins().iadd(states, offset);
    copy_native_deopt_state(builder, pointer_type, destination, deopt_out);
    let next = builder.ins().iadd_imm(index, 1);
    builder
        .ins()
        .store(MemFlagsData::new(), next, next_pointer, 0);
    let link = builder.ins().uextend(types::I64, next);
    builder.ins().jump(ready, &[link.into()]);

    builder.switch_to_block(ready);
    builder.block_params(ready)[0]
}

fn publish_native_fiber_suspension_link(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    link: ir::Value,
) {
    builder.ins().store(
        MemFlagsData::new(),
        link,
        deopt_out,
        std::mem::offset_of!(crate::JitDeoptState, delegation_handle) as i32,
    );
}

/// Splits a compiled userland call into its normal invocation and the exact
/// continuation result supplied when a suspended callee has completed. The
/// resume loader places typed control in `pending_*`; consuming it here avoids
/// re-invoking the callee or routing a stable target through the dispatcher.
fn begin_native_call_or_resume(
    builder: &mut FunctionBuilder<'_>,
    pending_status: Variable,
    pending_value: Variable,
    expected_return_status: u32,
    result_out: ir::Value,
    resume_state: ir::Value,
    deopt_out: ir::Value,
) -> ir::Block {
    let invoke = builder.create_block();
    let resumed = builder.create_block();
    let completed = builder.create_block();
    let propagate = builder.create_block();
    builder.append_block_param(completed, types::I64);

    let status = builder.use_var(pending_status);
    let normal = builder.ins().icmp_imm(
        IntCC::Equal,
        status,
        i64::from(crate::JitCallStatus::CONTINUE.0),
    );
    builder.ins().brif(normal, invoke, &[], resumed, &[]);

    builder.switch_to_block(resumed);
    let value = builder.use_var(pending_value);
    let clear = builder
        .ins()
        .iconst(types::I32, i64::from(crate::JitCallStatus::CONTINUE.0));
    builder.def_var(pending_status, clear);
    let returned = builder
        .ins()
        .icmp_imm(IntCC::Equal, status, i64::from(expected_return_status));
    builder
        .ins()
        .brif(returned, completed, &[value.into()], propagate, &[]);

    builder.switch_to_block(propagate);
    let pointer_type = builder.func.dfg.value_type(resume_state);
    copy_native_deopt_state(builder, pointer_type, deopt_out, resume_state);
    builder
        .ins()
        .store(MemFlagsData::new(), value, result_out, 0);
    return_native_or_fragment_control(builder, status, result_out);

    builder.switch_to_block(invoke);
    completed
}

#[allow(clippy::too_many_arguments)]
fn publish_native_continuation_state(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    function: FunctionId,
    local_count: u32,
    continuation_id: u32,
    live_locals: &[LocalId],
    locals: &NativeLocalMap,
    native_version: u32,
) -> Result<(), CraneliftLoweringError> {
    let store_i32 = |builder: &mut FunctionBuilder<'_>, offset: usize, value: u32| {
        let value = builder.ins().iconst(types::I32, i64::from(value));
        builder
            .ins()
            .store(MemFlagsData::new(), value, deopt_out, offset as i32);
    };
    store_i32(
        builder,
        std::mem::offset_of!(crate::JitDeoptState, function_id),
        function.raw(),
    );
    store_i32(
        builder,
        std::mem::offset_of!(crate::JitDeoptState, continuation_id),
        continuation_id,
    );
    store_i32(
        builder,
        std::mem::offset_of!(crate::JitDeoptState, slot_count),
        local_count,
    );
    store_i32(
        builder,
        std::mem::offset_of!(crate::JitDeoptState, native_version),
        native_version,
    );
    publish_native_local_masks(builder, deopt_out, live_locals);
    if !copy_native_local_state_values(
        builder,
        deopt_out,
        locals,
        live_locals,
        NativeLocalCopyDirection::FrameToState,
    )? {
        for local in live_locals {
            let value = use_local_variable(builder, locals, *local)?;
            let offset = std::mem::offset_of!(crate::JitDeoptState, slots)
                .saturating_add(local.index().saturating_mul(8));
            builder
                .ins()
                .store(MemFlagsData::new(), value, deopt_out, offset as i32);
        }
    }
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().store(
        MemFlagsData::new(),
        zero,
        deopt_out,
        std::mem::offset_of!(crate::JitDeoptState, initialized_register_mask) as i32,
    );
    Ok(())
}

fn publish_native_register_state(
    builder: &mut FunctionBuilder<'_>,
    state_out: ir::Value,
    registers: &NativeRegisterMap,
    live_registers: &[RegId],
) -> Result<(), CraneliftLoweringError> {
    let live_values = live_registers
        .iter()
        .copied()
        .map(|register| Ok((register, use_region_register(builder, registers, register)?)))
        .collect::<Result<Vec<_>, CraneliftLoweringError>>()?;
    publish_native_register_values(builder, state_out, &live_values)
}

fn publish_native_register_values(
    builder: &mut FunctionBuilder<'_>,
    state_out: ir::Value,
    live_values: &[(RegId, ir::Value)],
) -> Result<(), CraneliftLoweringError> {
    if live_values.len() > crate::JIT_DEOPT_MAX_REGISTERS {
        return Err(CraneliftLoweringError::new(
            "JIT_CRANELIFT_TRANSITION_REGISTER_LIMIT",
            format!(
                "native transition requires {} registers but the ABI supports {}",
                live_values.len(),
                crate::JIT_DEOPT_MAX_REGISTERS
            ),
        ));
    }
    // Snapshot slots are an ABI shared with the statically generated resume
    // loader. Never filter or compact this list independently: doing so moves
    // every later value to a different slot and restores it into the wrong
    // SSA register. A required value missing at this program point is a
    // lowering error, not an optional snapshot entry.
    let initialized_count = live_values.len();
    let initialized_mask = if initialized_count >= u64::BITS as usize {
        u64::MAX
    } else {
        1_u64
            .checked_shl(u32::try_from(initialized_count).unwrap_or(u32::MAX))
            .unwrap_or(0)
            .saturating_sub(1)
    };
    let initialized = builder.ins().iconst(types::I64, initialized_mask as i64);
    builder.ins().store(
        MemFlagsData::new(),
        initialized,
        state_out,
        std::mem::offset_of!(crate::JitDeoptState, initialized_register_mask) as i32,
    );
    for (snapshot_slot, (register, value)) in live_values.iter().copied().enumerate() {
        let register_id = builder.ins().iconst(types::I32, i64::from(register.raw()));
        let id_offset = std::mem::offset_of!(crate::JitDeoptState, register_ids)
            .saturating_add(snapshot_slot.saturating_mul(4));
        builder.ins().store(
            MemFlagsData::new(),
            register_id,
            state_out,
            id_offset as i32,
        );
        let value = if builder.func.dfg.value_type(value) == types::I64 {
            value
        } else {
            builder.ins().uextend(types::I64, value)
        };
        let offset = std::mem::offset_of!(crate::JitDeoptState, registers)
            .saturating_add(snapshot_slot.saturating_mul(8));
        builder
            .ins()
            .store(MemFlagsData::new(), value, state_out, offset as i32);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn lower_native_return_check_with_frame_cleanup(
    module: &mut JITModule,
    builder: &mut FunctionBuilder<'_>,
    native_operations: GenericNativeOperations,
    runtime: ir::Value,
    value_release_commit: ir::FuncRef,
    function: FunctionId,
    local_count: u32,
    failure_continuation: u32,
    native_version: u32,
    value: ir::Value,
    input_is_owned: bool,
    locals: &NativeLocalMap,
    value_flow: &ExecutableValueFlow,
    result_out: ir::Value,
    deopt_out: ir::Value,
) -> Result<ir::Value, CraneliftLoweringError> {
    let helper = native_operations.return_check.ok_or_else(|| {
        CraneliftLoweringError::new(
            "JIT_CRANELIFT_REJECT_NATIVE_OPERATION",
            "native return check has no declared helper",
        )
    })?;
    let runtime_view = lower_active_runtime_view(builder, deopt_out);
    let function_contracts = builder.ins().load(
        module.target_config().pointer_type(),
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_function_contracts) as i32,
    );
    let function_contract = builder.ins().iadd_imm(
        function_contracts,
        i64::try_from(
            function
                .index()
                .saturating_mul(std::mem::size_of::<crate::JitNativeFunctionContractView>()),
        )
        .unwrap_or(i64::MAX),
    );
    let return_contract = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        function_contract,
        std::mem::offset_of!(crate::JitNativeFunctionContractView, return_contract) as i32,
    );
    let call = call_native_helper(
        module,
        builder,
        helper,
        &[value, return_contract, result_out],
    );
    let status = builder.inst_results(call)[0];
    let checked = builder
        .ins()
        .load(types::I64, MemFlagsData::new(), result_out, 0);
    let admitted = builder.create_block();
    let failed = builder.create_block();
    let ok = builder.ins().icmp_imm(IntCC::Equal, status, 0);
    builder.ins().brif(ok, admitted, &[], failed, &[]);

    builder.switch_to_block(failed);
    if input_is_owned {
        let _ = lower_guarded_value_owner_change(
            builder,
            false,
            value,
            deopt_out,
            runtime,
            value_release_commit,
        )?;
    }
    terminators::lower_owned_frame_locals(
        module,
        builder,
        locals,
        runtime,
        value_release_commit,
        value_flow,
        function,
        deopt_out,
    )?;
    // The type failure is raised after the innermost finally has completed.
    // Publishing the earlier Return/ReturnReference continuation would make
    // native unwind select that same finally a second time. The callee frame
    // is already released here, so publish only the EndFinally control point;
    // no callee local remains live across this terminal throw.
    publish_native_continuation_state(
        builder,
        deopt_out,
        function,
        local_count,
        failure_continuation,
        &[],
        locals,
        native_version,
    )?;
    let (failure_status, failure_value) =
        select_generated_release_control(builder, deopt_out, status, checked);
    builder
        .ins()
        .store(MemFlagsData::new(), failure_value, result_out, 0);
    return_native_or_fragment_control(builder, failure_status, result_out);

    builder.switch_to_block(admitted);
    if input_is_owned {
        let unchanged = builder.ins().icmp(IntCC::Equal, checked, value);
        let preserve = builder.create_block();
        let release = builder.create_block();
        let done = builder.create_block();
        builder.ins().brif(unchanged, preserve, &[], release, &[]);

        builder.switch_to_block(release);
        let _ = lower_guarded_value_owner_change(
            builder,
            false,
            value,
            deopt_out,
            runtime,
            value_release_commit,
        )?;
        builder.ins().jump(done, &[]);

        builder.switch_to_block(preserve);
        builder.ins().jump(done, &[]);

        builder.switch_to_block(done);
    }
    Ok(checked)
}
fn lower_value_has_tag(builder: &mut FunctionBuilder<'_>, value: ir::Value, tag: u64) -> ir::Value {
    let encoded_tag = builder
        .ins()
        .band_imm(value, crate::JIT_VALUE_RUNTIME_KIND_MASK as i64);
    builder
        .ins()
        .icmp_imm(IntCC::Equal, encoded_tag, tag as i64)
}

fn lower_is_runtime_handle(builder: &mut FunctionBuilder<'_>, value: ir::Value) -> ir::Value {
    let tag = builder
        .ins()
        .band_imm(value, crate::JIT_VALUE_TAG_MASK as i64);
    builder
        .ins()
        .icmp_imm(IntCC::Equal, tag, crate::JIT_VALUE_RUNTIME_TAG as i64)
}

fn lower_value_has_namespace_tag(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    tag: u64,
) -> ir::Value {
    let encoded_tag = builder
        .ins()
        .band_imm(value, crate::JIT_VALUE_TAG_MASK as i64);
    builder
        .ins()
        .icmp_imm(IntCC::Equal, encoded_tag, tag as i64)
}

#[allow(clippy::too_many_arguments)]
#[derive(Clone, Copy)]
struct NativeOptimizingTransition<'a> {
    runtime: ir::Value,
    result_out: ir::Value,
    deopt_out: ir::Value,
    function: FunctionId,
    local_count: u32,
    continuation_id: u32,
    live_locals: &'a [LocalId],
    locals: &'a NativeLocalMap,
    live_values: &'a [(RegId, ir::Value)],
    native_version: u32,
    value_release_commit: ir::FuncRef,
    frame_alloc: Option<NativeHelper>,
    frame_release: Option<NativeHelper>,
    reference_payload_proof: NativeReferencePayloadProof,
}

/// Compile-time witness that every value capable of carrying a direct
/// reference into this optimizing region passed the total native publication
/// admission. The constructor remains private to the admission module.
#[derive(Clone, Copy)]
struct NativeReferencePayloadProof(());

impl NativeOptimizingTransition<'_> {
    fn emit_exact_throw(
        self,
        builder: &mut FunctionBuilder<'_>,
        detail: ir::Value,
        value: ir::Value,
    ) -> Result<(), CraneliftLoweringError> {
        let status = builder
            .ins()
            .iconst(types::I32, i64::from(crate::JitCallStatus::THROW.0));
        self.emit_control(builder, status, detail, value)
    }

    fn emit_exact_runtime_error(
        self,
        builder: &mut FunctionBuilder<'_>,
        detail: ir::Value,
        value: ir::Value,
    ) -> Result<(), CraneliftLoweringError> {
        let status = builder
            .ins()
            .iconst(types::I32, i64::from(crate::JitCallStatus::RUNTIME_ERROR.0));
        self.emit_control(builder, status, detail, value)
    }

    fn emit_control(
        self,
        builder: &mut FunctionBuilder<'_>,
        status: ir::Value,
        detail: ir::Value,
        value: ir::Value,
    ) -> Result<(), CraneliftLoweringError> {
        self.emit_control_with_fiber_link(builder, status, detail, value, None)
    }

    fn emit_control_with_fiber_link(
        self,
        builder: &mut FunctionBuilder<'_>,
        status: ir::Value,
        detail: ir::Value,
        value: ir::Value,
        fiber_link: Option<ir::Value>,
    ) -> Result<(), CraneliftLoweringError> {
        publish_native_continuation_state(
            builder,
            self.deopt_out,
            self.function,
            self.local_count,
            self.continuation_id,
            self.live_locals,
            self.locals,
            self.native_version,
        )?;
        publish_native_register_values(builder, self.deopt_out, self.live_values)?;
        if let Some(fiber_link) = fiber_link {
            publish_native_fiber_suspension_link(builder, self.deopt_out, fiber_link);
        }
        builder.ins().store(
            MemFlagsData::new(),
            detail,
            self.deopt_out,
            std::mem::offset_of!(crate::JitDeoptState, control_reserved) as i32,
        );
        builder
            .ins()
            .store(MemFlagsData::new(), value, self.result_out, 0);
        return_native_or_fragment_control(builder, status, self.result_out);

        let unreachable = builder.create_block();
        builder.switch_to_block(unreachable);
        builder.seal_block(unreachable);
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct EmittedOptimizingInstruction {
    pub(super) class: crate::JitProductionLoweringClass,
}

fn lower_optimizing_slot_address(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let view = lower_active_runtime_view(builder, deopt_out);
    let direct_slots = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_slots) as i32,
    );
    let index = builder.ins().ireduce(types::I32, value);
    let direct_index = builder
        .ins()
        .iadd_imm(index, -i64::from(crate::JIT_NATIVE_DIRECT_VALUE_INDEX_BASE));
    let direct_index = builder.ins().uextend(pointer_type, direct_index);
    let direct_offset = builder.ins().ishl_imm(direct_index, 5);
    builder.ins().iadd(direct_slots, direct_offset)
}

/// Loads one packed receiver/capture directly from the immutable prepared
/// closure record. Region construction proves the exact closure identity and
/// capture shape; generated code therefore performs no per-call kind, arity,
/// or descriptor validation.
fn lower_optimizing_prepared_closure_argument(
    builder: &mut FunctionBuilder<'_>,
    closure: ir::Value,
    bound_object_count: usize,
    capture_index: Option<usize>,
    deopt_out: ir::Value,
) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let slot = lower_optimizing_slot_address(builder, closure, deopt_out);
    let closure_view = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    if bound_object_count != 0 && capture_index.is_none() {
        return builder.ins().load(
            types::I64,
            MemFlagsData::new(),
            closure_view,
            std::mem::offset_of!(crate::JitNativePreparedClosureView, implicit_this) as i32,
        );
    }
    let captures = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        closure_view,
        std::mem::offset_of!(crate::JitNativePreparedClosureView, captures) as i32,
    );
    builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        captures,
        i32::try_from(capture_index.unwrap_or(0).saturating_mul(8)).unwrap_or(i32::MAX),
    )
}

fn lower_trusted_request_local_reference(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    function: FunctionId,
    local: LocalId,
) -> ir::Value {
    let slot = lower_trusted_request_local_slot(builder, deopt_out, function, local);
    builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeRequestLocalSlot, encoded) as i32,
    )
}

fn lower_trusted_request_local_slot(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    function: FunctionId,
    local: LocalId,
) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let view = lower_active_runtime_view(builder, deopt_out);
    let offsets = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(
            crate::JitNativeRuntimeView,
            trusted_request_local_function_offsets,
        ) as i32,
    );
    let function_offset = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        offsets,
        i32::try_from(function.index().saturating_mul(4)).unwrap_or(i32::MAX),
    );
    let index = builder
        .ins()
        .iadd_imm(function_offset, i64::from(local.raw()));
    let index = builder.ins().uextend(pointer_type, index);
    let slot_offset = builder.ins().ishl_imm(index, 4);
    let slots = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_request_local_slots) as i32,
    );
    builder.ins().iadd(slots, slot_offset)
}

/// Reserve one request-owned direct value slot without entering Rust.
///
/// Final-owner release links retired slots through `payload`; allocation
/// consumes that request-owned free list before advancing the high-water.
fn lower_reserve_direct_value_index(
    builder: &mut FunctionBuilder<'_>,
    deopt_out: ir::Value,
    rejected: Option<ir::Block>,
) -> ir::Value {
    let reuse = builder.create_block();
    let bump = builder.create_block();
    let bump_accepted = builder.create_block();
    let ready = builder.create_block();
    builder.append_block_param(ready, types::I32);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let view = lower_active_runtime_view(builder, deopt_out);
    let free_head_ptr = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_free_head) as i32,
    );
    let free_head = builder
        .ins()
        .load(types::I32, MemFlagsData::new(), free_head_ptr, 0);
    let has_free = builder.ins().icmp_imm(
        IntCC::NotEqual,
        free_head,
        i64::from(crate::JIT_NATIVE_DIRECT_ARRAY_FREE_NONE),
    );
    builder.ins().brif(has_free, reuse, &[], bump, &[]);

    builder.switch_to_block(reuse);
    let slots = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_slots) as i32,
    );
    let wide_index = builder.ins().uextend(pointer_type, free_head);
    let slot_offset = builder.ins().ishl_imm(wide_index, 5);
    let slot = builder.ins().iadd(slots, slot_offset);
    let previous = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    builder
        .ins()
        .store(MemFlagsData::new(), previous, free_head_ptr, 0);
    let reused_bytes_ptr = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_reused_bytes) as i32,
    );
    let reused_bytes = builder
        .ins()
        .load(types::I64, MemFlagsData::new(), reused_bytes_ptr, 0);
    let reused_bytes = builder.ins().iadd_imm(
        reused_bytes,
        i64::try_from(std::mem::size_of::<crate::JitNativeValueSlot>()).unwrap_or(i64::MAX),
    );
    builder
        .ins()
        .store(MemFlagsData::new(), reused_bytes, reused_bytes_ptr, 0);
    builder.ins().jump(ready, &[free_head.into()]);

    builder.switch_to_block(bump);
    let next_ptr = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_next) as i32,
    );
    let next = builder
        .ins()
        .load(types::I32, MemFlagsData::new(), next_ptr, 0);
    if let Some(rejected) = rejected {
        let has_room = builder.ins().icmp_imm(
            IntCC::UnsignedLessThan,
            next,
            crate::JIT_NATIVE_DIRECT_VALUE_CAPACITY as i64,
        );
        builder
            .ins()
            .brif(has_room, bump_accepted, &[], rejected, &[]);
    } else {
        // Total native users reserve their complete request-owned slot budget
        // in the function-entry admission block.
        builder.ins().jump(bump_accepted, &[]);
    }

    builder.switch_to_block(bump_accepted);
    let next_value = builder.ins().iadd_imm(next, 1);
    builder
        .ins()
        .store(MemFlagsData::new(), next_value, next_ptr, 0);
    builder.ins().jump(ready, &[next.into()]);

    builder.switch_to_block(ready);
    builder.block_params(ready)[0]
}

/// Binds one SSA local to an authoritative direct reference slot. Existing
/// references retain their identity; immediate scalars and already
/// authoritative direct handles transfer their existing owner into the new
/// cell without materializing a Rust `Value` or creating a second owner.
fn lower_optimizing_bind_direct_local_reference(
    builder: &mut FunctionBuilder<'_>,
    current: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    lower_optimizing_bind_direct_local_reference_with_owner(builder, current, false, transition)
}

/// Binds a borrowed published literal as a fresh reference payload owner.
///
/// Omitted by-reference defaults have no caller-local owner to transfer. The
/// reference must therefore retain the published array/string handle once;
/// otherwise the callee epilogue retires the unit literal after the first
/// invocation and a later call observes a recycled direct slot.
fn lower_optimizing_bind_borrowed_direct_reference(
    builder: &mut FunctionBuilder<'_>,
    current: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    lower_optimizing_bind_direct_local_reference_with_owner(builder, current, true, transition)
}

/// Materialize the authoritative reference cell used by a local or reference
/// return. `preserve_current_owner` is set for a return: the frame keeps its
/// current local owner until cleanup while the new reference payload acquires
/// an independent owner. Ordinary reference binding transfers the local owner
/// instead.
fn lower_optimizing_bind_direct_local_reference_with_owner(
    builder: &mut FunctionBuilder<'_>,
    current: ir::Value,
    preserve_current_owner: bool,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    let reference = lower_total_native_bind_reference(builder, current, transition.deopt_out);
    if preserve_current_owner {
        lower_optimizing_retain(builder, current, transition.deopt_out);
    }
    Ok(reference)
}

/// Materialize or reuse a direct reference cell after publication has proved
/// the payload representation and reserved the complete value-slot budget.
/// There is deliberately no operation-local rejection edge.
fn lower_total_native_bind_reference(
    builder: &mut FunctionBuilder<'_>,
    current: ir::Value,
    deopt_out: ir::Value,
) -> ir::Value {
    let existing = builder.create_block();
    let allocate = builder.create_block();
    let done = builder.create_block();
    builder.append_block_param(done, types::I64);
    let reference = lower_value_has_tag(builder, current, crate::JIT_VALUE_RUNTIME_REFERENCE_TAG);
    builder.ins().brif(reference, existing, &[], allocate, &[]);

    builder.switch_to_block(existing);
    builder.ins().jump(done, &[current.into()]);

    builder.switch_to_block(allocate);
    let slot_index = lower_reserve_direct_value_index(builder, deopt_out, None);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let runtime_view = lower_active_runtime_view(builder, deopt_out);
    let slots = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_slots) as i32,
    );
    let wide_index = builder.ins().uextend(pointer_type, slot_index);
    let slot_offset = builder.ins().ishl_imm(wide_index, 5);
    let slot = builder.ins().iadd(slots, slot_offset);
    let one = builder.ins().iconst(types::I32, 1);
    builder.ins().store(
        MemFlagsData::new(),
        one,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    let kind = builder.ins().iconst(
        types::I32,
        i64::from(crate::JIT_NATIVE_VALUE_VIEW_DIRECT_REFERENCE_SCALAR),
    );
    builder.ins().store(
        MemFlagsData::new(),
        kind,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, kind) as i32,
    );
    let flags = builder.ins().iconst(
        types::I32,
        i64::from(crate::JIT_NATIVE_REFERENCE_SCALAR_VIEW_ABI_VERSION),
    );
    builder.ins().store(
        MemFlagsData::new(),
        flags,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, flags) as i32,
    );
    let published = builder.ins().iconst(
        types::I32,
        i64::from(crate::JIT_NATIVE_REFERENCE_SCALAR_VIEW_PUBLISHED),
    );
    builder.ins().store(
        MemFlagsData::new(),
        published,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, reserved) as i32,
    );
    builder.ins().store(
        MemFlagsData::new(),
        current,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().store(
        MemFlagsData::new(),
        zero,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let encoded_index = builder.ins().iadd_imm(
        slot_index,
        i64::from(crate::JIT_NATIVE_DIRECT_VALUE_INDEX_BASE),
    );
    let encoded_index = builder.ins().uextend(types::I64, encoded_index);
    let reference = builder
        .ins()
        .bor_imm(encoded_index, crate::JIT_VALUE_RUNTIME_REFERENCE_TAG as i64);
    builder.ins().jump(done, &[reference.into()]);

    builder.switch_to_block(done);
    builder.block_params(done)[0]
}

include!("cranelift_lowering/direct_array_lowering.rs");

/// Compare PHP array keys without reconstructing a Rust `Value` or crossing a
/// runtime-helper boundary. Integer keys compare their native payloads,
/// including namespace-colliding integers published as direct records. String
/// keys compare their publication-owned byte views, so independently encoded
/// handles with equal contents name the same PHP array element.
fn lower_native_string_key_descriptor(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) -> (ir::Value, ir::Value, ir::Value) {
    let inspect_constant = builder.create_block();
    let runtime = builder.create_block();
    let constant = builder.create_block();
    let invalid = builder.create_block();
    let merge = builder.create_block();
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    builder.append_block_param(merge, types::I8);
    builder.append_block_param(merge, types::I64);
    builder.append_block_param(merge, pointer_type);

    let runtime_string = lower_value_has_tag(builder, value, crate::JIT_VALUE_RUNTIME_STRING_TAG);
    builder
        .ins()
        .brif(runtime_string, runtime, &[], inspect_constant, &[]);

    builder.switch_to_block(inspect_constant);
    let constant_tag = lower_value_has_namespace_tag(builder, value, crate::JIT_VALUE_CONSTANT_TAG);
    let index = builder.ins().ireduce(types::I32, value);
    let runtime_view = lower_active_runtime_view(builder, deopt_out);
    let count = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_constant_view_count) as i32,
    );
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index, count);
    let admitted = builder.ins().band(constant_tag, in_bounds);
    builder.ins().brif(admitted, constant, &[], invalid, &[]);

    builder.switch_to_block(runtime);
    let runtime_index = builder.ins().ireduce(types::I32, value);
    let direct = builder.ins().icmp_imm(
        IntCC::UnsignedGreaterThanOrEqual,
        runtime_index,
        i64::from(crate::JIT_NATIVE_DIRECT_VALUE_INDEX_BASE),
    );
    let first_direct = builder.ins().iconst(
        types::I64,
        (crate::JIT_VALUE_RUNTIME_STRING_TAG | u64::from(crate::JIT_NATIVE_DIRECT_VALUE_INDEX_BASE))
            as i64,
    );
    // Clamp rejected compatibility handles to the arena's demand-zero first
    // slot before loading. The `direct` bit remains part of admission below,
    // so the cold handle can never be mistaken for an authoritative string.
    let safe_value = builder.ins().select(direct, value, first_direct);
    let slot = lower_optimizing_slot_address(builder, safe_value, deopt_out);
    let kind = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, kind) as i32,
    );
    let flags = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, flags) as i32,
    );
    let length = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let bytes = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let kind_ok = builder.ins().icmp_imm(
        IntCC::Equal,
        kind,
        i64::from(crate::JIT_NATIVE_VALUE_VIEW_STRING),
    );
    let version_ok = builder.ins().icmp_imm(
        IntCC::Equal,
        flags,
        i64::from(crate::JIT_NATIVE_STRING_VIEW_ABI_VERSION),
    );
    let valid = builder.ins().band(kind_ok, version_ok);
    let valid = builder.ins().band(valid, direct);
    builder
        .ins()
        .jump(merge, &[valid.into(), length.into(), bytes.into()]);

    builder.switch_to_block(constant);
    let views = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_constant_views) as i32,
    );
    let wide_index = builder.ins().uextend(pointer_type, index);
    let offset = builder.ins().imul_imm(
        wide_index,
        i64::try_from(std::mem::size_of::<crate::JitNativeConstantView>()).unwrap_or(i64::MAX),
    );
    let descriptor = builder.ins().iadd(views, offset);
    let kind = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        descriptor,
        std::mem::offset_of!(crate::JitNativeConstantView, kind) as i32,
    );
    let length = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        descriptor,
        std::mem::offset_of!(crate::JitNativeConstantView, length) as i32,
    );
    let bytes = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        descriptor,
        std::mem::offset_of!(crate::JitNativeConstantView, bytes) as i32,
    );
    let valid = builder.ins().icmp_imm(
        IntCC::Equal,
        kind,
        i64::from(crate::JIT_NATIVE_CONSTANT_VIEW_STRING),
    );
    builder
        .ins()
        .jump(merge, &[valid.into(), length.into(), bytes.into()]);

    builder.switch_to_block(invalid);
    let no = builder.ins().iconst(types::I8, 0);
    let zero = builder.ins().iconst(types::I64, 0);
    let null = builder.ins().iconst(pointer_type, 0);
    builder
        .ins()
        .jump(merge, &[no.into(), zero.into(), null.into()]);

    builder.switch_to_block(merge);
    (
        builder.block_params(merge)[0],
        builder.block_params(merge)[1],
        builder.block_params(merge)[2],
    )
}

/// Classifies one authoritative native value as a PHP integer array key.
///
/// PHP array keys admit canonical decimal strings in addition to integer
/// values. Parse the stable native byte view directly in CLIF so lookup,
/// insertion, iteration, and auto-index state all share one representation
/// rule without a runtime helper or a Rust `Value` round trip.
fn lower_native_array_key_integer_candidate(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) -> (ir::Value, ir::Value) {
    let inspect_string = builder.create_block();
    let inspect_length = builder.create_block();
    let inspect_sign = builder.create_block();
    let inspect_first_digit = builder.create_block();
    let parse = builder.create_block();
    let inspect_digit = builder.create_block();
    let accumulate = builder.create_block();
    let finish = builder.create_block();
    let invalid = builder.create_block();
    let merge = builder.create_block();
    builder.append_block_param(inspect_first_digit, types::I64);
    builder.append_block_param(inspect_first_digit, types::I8);
    builder.append_block_param(parse, types::I64);
    builder.append_block_param(parse, types::I64);
    builder.append_block_param(parse, types::I8);
    builder.append_block_param(inspect_digit, types::I64);
    builder.append_block_param(inspect_digit, types::I64);
    builder.append_block_param(inspect_digit, types::I8);
    builder.append_block_param(accumulate, types::I64);
    builder.append_block_param(accumulate, types::I64);
    builder.append_block_param(accumulate, types::I8);
    builder.append_block_param(accumulate, types::I64);
    builder.append_block_param(finish, types::I64);
    builder.append_block_param(finish, types::I8);
    builder.append_block_param(merge, types::I8);
    builder.append_block_param(merge, types::I64);

    let (integer, raw) = lower_optimizing_integer_candidate(builder, value, deopt_out);
    builder.ins().brif(
        integer,
        merge,
        &[integer.into(), raw.into()],
        inspect_string,
        &[],
    );

    builder.switch_to_block(inspect_string);
    let (string, length, bytes) = lower_native_string_key_descriptor(builder, value, deopt_out);
    builder
        .ins()
        .brif(string, inspect_length, &[], invalid, &[]);

    builder.switch_to_block(inspect_length);
    let nonempty = builder.ins().icmp_imm(IntCC::NotEqual, length, 0);
    let bounded = builder
        .ins()
        .icmp_imm(IntCC::UnsignedLessThanOrEqual, length, 20);
    let admitted = builder.ins().band(nonempty, bounded);
    builder
        .ins()
        .brif(admitted, inspect_sign, &[], invalid, &[]);

    builder.switch_to_block(inspect_sign);
    let first = builder.ins().load(types::I8, MemFlagsData::new(), bytes, 0);
    let negative = builder.ins().icmp_imm(IntCC::Equal, first, b'-' as i64);
    let one = builder.ins().iconst(types::I64, 1);
    let zero = builder.ins().iconst(types::I64, 0);
    let start = builder.ins().select(negative, one, zero);
    let has_digit = builder.ins().icmp(IntCC::UnsignedLessThan, start, length);
    builder.ins().brif(
        has_digit,
        inspect_first_digit,
        &[start.into(), negative.into()],
        invalid,
        &[],
    );

    builder.switch_to_block(inspect_first_digit);
    let first_index = builder.block_params(inspect_first_digit)[0];
    let negative = builder.block_params(inspect_first_digit)[1];
    let pointer_type = builder.func.dfg.value_type(bytes);
    let first_offset = if pointer_type == types::I64 {
        first_index
    } else {
        builder.ins().ireduce(pointer_type, first_index)
    };
    let first_pointer = builder.ins().iadd(bytes, first_offset);
    let first_digit = builder
        .ins()
        .load(types::I8, MemFlagsData::new(), first_pointer, 0);
    let zero_digit = builder
        .ins()
        .icmp_imm(IntCC::Equal, first_digit, b'0' as i64);
    let digit_count = builder.ins().isub(length, first_index);
    let multiple_digits = builder
        .ins()
        .icmp_imm(IntCC::UnsignedGreaterThan, digit_count, 1);
    // PHP admits "0" but keeps "-0" and every leading-zero spelling as a
    // string key.
    let noncanonical_zero = builder.ins().bor(negative, multiple_digits);
    let noncanonical_zero = builder.ins().band(zero_digit, noncanonical_zero);
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().brif(
        noncanonical_zero,
        invalid,
        &[],
        parse,
        &[first_index.into(), zero.into(), negative.into()],
    );

    builder.switch_to_block(parse);
    let index = builder.block_params(parse)[0];
    let magnitude = builder.block_params(parse)[1];
    let negative = builder.block_params(parse)[2];
    let complete = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder.ins().brif(
        complete,
        finish,
        &[magnitude.into(), negative.into()],
        inspect_digit,
        &[index.into(), magnitude.into(), negative.into()],
    );

    builder.switch_to_block(inspect_digit);
    let index = builder.block_params(inspect_digit)[0];
    let magnitude = builder.block_params(inspect_digit)[1];
    let negative = builder.block_params(inspect_digit)[2];
    let offset = if pointer_type == types::I64 {
        index
    } else {
        builder.ins().ireduce(pointer_type, index)
    };
    let pointer = builder.ins().iadd(bytes, offset);
    let byte = builder
        .ins()
        .load(types::I8, MemFlagsData::new(), pointer, 0);
    let at_least_zero =
        builder
            .ins()
            .icmp_imm(IntCC::UnsignedGreaterThanOrEqual, byte, b'0' as i64);
    let at_most_nine = builder
        .ins()
        .icmp_imm(IntCC::UnsignedLessThanOrEqual, byte, b'9' as i64);
    let decimal = builder.ins().band(at_least_zero, at_most_nine);
    let digit8 = builder.ins().iadd_imm(byte, -(b'0' as i64));
    let digit = builder.ins().uextend(types::I64, digit8);
    builder.ins().brif(
        decimal,
        accumulate,
        &[
            index.into(),
            magnitude.into(),
            negative.into(),
            digit.into(),
        ],
        invalid,
        &[],
    );

    builder.switch_to_block(accumulate);
    let index = builder.block_params(accumulate)[0];
    let magnitude = builder.block_params(accumulate)[1];
    let negative = builder.block_params(accumulate)[2];
    let digit = builder.block_params(accumulate)[3];
    let quotient = builder.ins().iconst(types::I64, 922_337_203_685_477_580);
    let over_quotient = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThan, magnitude, quotient);
    let at_quotient = builder.ins().icmp(IntCC::Equal, magnitude, quotient);
    let positive_remainder = builder.ins().iconst(types::I64, 7);
    let negative_remainder = builder.ins().iconst(types::I64, 8);
    let remainder = builder
        .ins()
        .select(negative, negative_remainder, positive_remainder);
    let over_remainder = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThan, digit, remainder);
    let terminal_overflow = builder.ins().band(at_quotient, over_remainder);
    let overflow = builder.ins().bor(over_quotient, terminal_overflow);
    let multiplied = builder.ins().imul_imm(magnitude, 10);
    let next_magnitude = builder.ins().iadd(multiplied, digit);
    let next_index = builder.ins().iadd_imm(index, 1);
    builder.ins().brif(
        overflow,
        invalid,
        &[],
        parse,
        &[next_index.into(), next_magnitude.into(), negative.into()],
    );

    builder.switch_to_block(finish);
    let magnitude = builder.block_params(finish)[0];
    let negative = builder.block_params(finish)[1];
    let negated = builder.ins().ineg(magnitude);
    let raw = builder.ins().select(negative, negated, magnitude);
    let yes = builder.ins().iconst(types::I8, 1);
    builder.ins().jump(merge, &[yes.into(), raw.into()]);

    builder.switch_to_block(invalid);
    let no = builder.ins().iconst(types::I8, 0);
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().jump(merge, &[no.into(), zero.into()]);

    builder.switch_to_block(merge);
    (
        builder.block_params(merge)[0],
        builder.block_params(merge)[1],
    )
}

fn lower_native_scalar_constant_truthy(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) -> (ir::Value, ir::Value) {
    let published = builder.create_block();
    let invalid = builder.create_block();
    let merge = builder.create_block();
    builder.append_block_param(merge, types::I8);
    builder.append_block_param(merge, types::I8);
    let index = builder.ins().ireduce(types::I32, value);
    let constant = lower_value_has_namespace_tag(builder, value, crate::JIT_VALUE_CONSTANT_TAG);
    let runtime_view = lower_active_runtime_view(builder, deopt_out);
    let count = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_constant_view_count) as i32,
    );
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index, count);
    let admitted = builder.ins().band(constant, in_bounds);
    builder.ins().brif(admitted, published, &[], invalid, &[]);

    builder.switch_to_block(published);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let views = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_constant_views) as i32,
    );
    let wide_index = builder.ins().uextend(pointer_type, index);
    let offset = builder.ins().imul_imm(
        wide_index,
        i64::try_from(std::mem::size_of::<crate::JitNativeConstantView>()).unwrap_or(i64::MAX),
    );
    let descriptor = builder.ins().iadd(views, offset);
    let kind = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        descriptor,
        std::mem::offset_of!(crate::JitNativeConstantView, kind) as i32,
    );
    let payload = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        descriptor,
        std::mem::offset_of!(crate::JitNativeConstantView, length) as i32,
    );
    let is_null = builder.ins().icmp_imm(
        IntCC::Equal,
        kind,
        i64::from(crate::JIT_NATIVE_CONSTANT_VIEW_NULL),
    );
    let is_bool = builder.ins().icmp_imm(
        IntCC::Equal,
        kind,
        i64::from(crate::JIT_NATIVE_CONSTANT_VIEW_BOOL),
    );
    let is_int = builder.ins().icmp_imm(
        IntCC::Equal,
        kind,
        i64::from(crate::JIT_NATIVE_CONSTANT_VIEW_INT),
    );
    let is_float = builder.ins().icmp_imm(
        IntCC::Equal,
        kind,
        i64::from(crate::JIT_NATIVE_CONSTANT_VIEW_FLOAT),
    );
    let valid = builder.ins().bor(is_null, is_bool);
    let valid = builder.ins().bor(valid, is_int);
    let valid = builder.ins().bor(valid, is_float);
    let scalar_truthy = builder.ins().icmp_imm(IntCC::NotEqual, payload, 0);
    let float_magnitude = builder.ins().band_imm(payload, i64::MAX);
    let float_truthy = builder.ins().icmp_imm(IntCC::NotEqual, float_magnitude, 0);
    let truthy = builder.ins().select(is_float, float_truthy, scalar_truthy);
    let truthy = builder.ins().band_not(truthy, is_null);
    builder.ins().jump(merge, &[valid.into(), truthy.into()]);

    builder.switch_to_block(invalid);
    let no = builder.ins().iconst(types::I8, 0);
    builder.ins().jump(merge, &[no.into(), no.into()]);

    builder.switch_to_block(merge);
    (
        builder.block_params(merge)[0],
        builder.block_params(merge)[1],
    )
}

fn lower_native_array_key_equal(
    builder: &mut FunctionBuilder<'_>,
    lhs: ir::Value,
    rhs: ir::Value,
    deopt_out: ir::Value,
) -> ir::Value {
    let lhs = lower_normalize_native_array_key(builder, lhs, deopt_out);
    let rhs = lower_normalize_native_array_key(builder, rhs, deopt_out);
    let inspect_integer = builder.create_block();
    let inspect_encoded = builder.create_block();
    let inspect_strings = builder.create_block();
    let compare_length = builder.create_block();
    let compare_loop = builder.create_block();
    let compare_byte = builder.create_block();
    let next_byte = builder.create_block();
    let matched = builder.create_block();
    let different = builder.create_block();
    let merge = builder.create_block();
    builder.append_block_param(compare_loop, types::I64);
    builder.append_block_param(next_byte, types::I64);
    builder.append_block_param(merge, types::I8);

    let (lhs_integer, lhs_raw) = lower_native_array_key_integer_candidate(builder, lhs, deopt_out);
    let (rhs_integer, rhs_raw) = lower_native_array_key_integer_candidate(builder, rhs, deopt_out);
    let either_integer = builder.ins().bor(lhs_integer, rhs_integer);
    builder
        .ins()
        .brif(either_integer, inspect_integer, &[], inspect_encoded, &[]);

    builder.switch_to_block(inspect_integer);
    let both_integer = builder.ins().band(lhs_integer, rhs_integer);
    let same_integer = builder.ins().icmp(IntCC::Equal, lhs_raw, rhs_raw);
    let same_integer = builder.ins().band(both_integer, same_integer);
    builder
        .ins()
        .brif(same_integer, matched, &[], different, &[]);

    builder.switch_to_block(inspect_encoded);
    let identical = builder.ins().icmp(IntCC::Equal, lhs, rhs);
    builder
        .ins()
        .brif(identical, matched, &[], inspect_strings, &[]);

    builder.switch_to_block(inspect_strings);
    let (lhs_valid, lhs_length, lhs_bytes) =
        lower_native_string_key_descriptor(builder, lhs, deopt_out);
    let (rhs_valid, rhs_length, rhs_bytes) =
        lower_native_string_key_descriptor(builder, rhs, deopt_out);
    let descriptors_ok = builder.ins().band(lhs_valid, rhs_valid);
    builder
        .ins()
        .brif(descriptors_ok, compare_length, &[], different, &[]);

    builder.switch_to_block(compare_length);
    let same_length = builder.ins().icmp(IntCC::Equal, lhs_length, rhs_length);
    let zero = builder.ins().iconst(types::I64, 0);
    builder
        .ins()
        .brif(same_length, compare_loop, &[zero.into()], different, &[]);

    builder.switch_to_block(compare_loop);
    let index = builder.block_params(compare_loop)[0];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, lhs_length);
    builder
        .ins()
        .brif(exhausted, matched, &[], compare_byte, &[]);

    builder.switch_to_block(compare_byte);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let byte_index = if pointer_type == types::I64 {
        index
    } else {
        builder.ins().ireduce(pointer_type, index)
    };
    let lhs_address = builder.ins().iadd(lhs_bytes, byte_index);
    let rhs_address = builder.ins().iadd(rhs_bytes, byte_index);
    let lhs_byte = builder
        .ins()
        .load(types::I8, MemFlagsData::new(), lhs_address, 0);
    let rhs_byte = builder
        .ins()
        .load(types::I8, MemFlagsData::new(), rhs_address, 0);
    let equal = builder.ins().icmp(IntCC::Equal, lhs_byte, rhs_byte);
    builder
        .ins()
        .brif(equal, next_byte, &[index.into()], different, &[]);

    builder.switch_to_block(next_byte);
    let index = builder.block_params(next_byte)[0];
    let next = builder.ins().iadd_imm(index, 1);
    builder.ins().jump(compare_loop, &[next.into()]);

    builder.switch_to_block(matched);
    let yes = builder.ins().iconst(types::I8, 1);
    builder.ins().jump(merge, &[yes.into()]);

    builder.switch_to_block(different);
    let no = builder.ins().iconst(types::I8, 0);
    builder.ins().jump(merge, &[no.into()]);

    builder.switch_to_block(merge);
    builder.block_params(merge)[0]
}

/// Normalizes PHP `null` array keys to the request-owned canonical empty
/// string. The selected handle stays in the authoritative native value plane;
/// insertion retains it only when a new array entry takes ownership.
fn lower_normalize_native_array_key(
    builder: &mut FunctionBuilder<'_>,
    key: ir::Value,
    deopt_out: ir::Value,
) -> ir::Value {
    let null = builder
        .ins()
        .iconst(types::I64, crate::jit_encode_constant(u32::MAX));
    let is_null = builder.ins().icmp(IntCC::Equal, key, null);
    let view = lower_active_runtime_view(builder, deopt_out);
    let empty = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, trusted_empty_string_key) as i32,
    );
    builder.ins().select(is_null, empty, key)
}

#[allow(clippy::too_many_arguments)]
fn lower_total_direct_foreach_init(
    builder: &mut FunctionBuilder<'_>,
    source: ir::Value,
    retain_source: bool,
    deopt_out: ir::Value,
) -> ir::Value {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let source_slot = lower_optimizing_slot_address(builder, source, deopt_out);
    let length = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        source_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let next = lower_reserve_direct_value_index(builder, deopt_out, None);
    if retain_source {
        lower_optimizing_retain(builder, source, deopt_out);
    }
    let view = lower_active_runtime_view(builder, deopt_out);
    let slots = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_slots) as i32,
    );
    let next_pointer = builder.ins().uextend(pointer_type, next);
    let slot_offset = builder.ins().ishl_imm(next_pointer, 5);
    let slot = builder.ins().iadd(slots, slot_offset);
    for (value, offset) in [
        (
            builder.ins().iconst(types::I32, 1),
            std::mem::offset_of!(crate::JitNativeValueSlot, refcount),
        ),
        (
            builder.ins().iconst(
                types::I32,
                i64::from(crate::JIT_NATIVE_VALUE_VIEW_DIRECT_FOREACH),
            ),
            std::mem::offset_of!(crate::JitNativeValueSlot, kind),
        ),
        (
            builder.ins().iconst(
                types::I32,
                i64::from(crate::JIT_NATIVE_DIRECT_ARRAY_ABI_VERSION),
            ),
            std::mem::offset_of!(crate::JitNativeValueSlot, flags),
        ),
        (
            builder.ins().ireduce(types::I32, length),
            std::mem::offset_of!(crate::JitNativeValueSlot, reserved),
        ),
    ] {
        builder
            .ins()
            .store(MemFlagsData::new(), value, slot, offset as i32);
    }
    builder.ins().store(
        MemFlagsData::new(),
        source,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().store(
        MemFlagsData::new(),
        zero,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let encoded_index = builder
        .ins()
        .iadd_imm(next, i64::from(crate::JIT_NATIVE_DIRECT_VALUE_INDEX_BASE));
    let encoded_index = builder.ins().uextend(types::I64, encoded_index);
    builder
        .ins()
        .bor_imm(encoded_index, crate::JIT_VALUE_RUNTIME_ITERATOR_TAG as i64)
}

fn lower_total_direct_foreach_next(
    builder: &mut FunctionBuilder<'_>,
    iterator: ir::Value,
    retain_key: bool,
    deopt_out: ir::Value,
) -> (ir::Value, ir::Value, ir::Value) {
    let slot = lower_optimizing_slot_address(builder, iterator, deopt_out);
    let source = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let cursor = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let length = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, reserved) as i32,
    );
    let length = builder.ins().uextend(types::I64, length);
    let present = builder.create_block();
    let exhausted = builder.create_block();
    let done = builder.create_block();
    builder.append_block_param(done, types::I64);
    builder.append_block_param(done, types::I64);
    builder.append_block_param(done, types::I64);
    let has_value = builder.ins().icmp(IntCC::UnsignedLessThan, cursor, length);
    builder.ins().brif(has_value, present, &[], exhausted, &[]);

    builder.switch_to_block(present);
    let source_slot = lower_optimizing_slot_address(builder, source, deopt_out);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let entries = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        source_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let entry = lower_optimizing_direct_array_entry_address(builder, entries, cursor, pointer_type);
    let key = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        entry,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, key) as i32,
    );
    let value = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        entry,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
    );
    if retain_key {
        lower_optimizing_retain(builder, key, deopt_out);
    }
    lower_optimizing_retain(builder, value, deopt_out);
    let next = builder.ins().iadd_imm(cursor, 1);
    builder.ins().store(
        MemFlagsData::new(),
        next,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let one = builder.ins().iconst(types::I64, 1);
    builder
        .ins()
        .jump(done, &[key.into(), value.into(), one.into()]);

    builder.switch_to_block(exhausted);
    let null = builder
        .ins()
        .iconst(types::I64, crate::jit_encode_constant(u32::MAX));
    let zero = builder.ins().iconst(types::I64, 0);
    builder
        .ins()
        .jump(done, &[null.into(), null.into(), zero.into()]);

    builder.switch_to_block(done);
    let values = builder.block_params(done);
    (values[0], values[1], values[2])
}

fn lower_total_direct_foreach_reference_init(
    builder: &mut FunctionBuilder<'_>,
    local: LocalId,
    locals: &NativeLocalMap,
    local_is_reference: bool,
    deopt_out: ir::Value,
) -> Result<ir::Value, CraneliftLoweringError> {
    let local_owner = use_local_variable(builder, locals, local)?;
    let array = if local_is_reference {
        let slot = lower_optimizing_slot_address(builder, local_owner, deopt_out);
        builder.ins().load(
            types::I64,
            MemFlagsData::new(),
            slot,
            std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
        )
    } else {
        local_owner
    };
    let (_, length, entries) = lower_total_native_array_descriptor(builder, array, deopt_out);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let zero = builder.ins().iconst(types::I64, 0);
    let scan = builder.create_block();
    let wrap = builder.create_block();
    let transformed = builder.create_block();
    builder.append_block_param(scan, types::I64);
    builder.ins().jump(scan, &[zero.into()]);

    builder.switch_to_block(scan);
    let index = builder.block_params(scan)[0];
    let complete = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder.ins().brif(complete, transformed, &[], wrap, &[]);

    builder.switch_to_block(wrap);
    let entry = lower_optimizing_direct_array_entry_address(builder, entries, index, pointer_type);
    let value = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        entry,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
    );
    let reference = lower_total_native_bind_reference(builder, value, deopt_out);
    builder.ins().store(
        MemFlagsData::new(),
        reference,
        entry,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
    );
    let next = builder.ins().iadd_imm(index, 1);
    builder.ins().jump(scan, &[next.into()]);

    builder.switch_to_block(transformed);
    let live_source = if local_is_reference {
        local_owner
    } else {
        lower_total_native_bind_reference(builder, array, deopt_out)
    };
    define_local_variable(builder, locals, local, live_source)?;
    lower_mark_native_roots_dirty(builder, deopt_out);

    // The local and iterator independently own the same live source
    // reference. Publication reserved every element reference plus these two
    // descriptor slots before the region became callable.
    lower_optimizing_retain(builder, live_source, deopt_out);
    let next = lower_reserve_direct_value_index(builder, deopt_out, None);
    let view = lower_active_runtime_view(builder, deopt_out);
    let slots = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, direct_value_slots) as i32,
    );
    let next_pointer = builder.ins().uextend(pointer_type, next);
    let slot_offset = builder.ins().ishl_imm(next_pointer, 5);
    let slot = builder.ins().iadd(slots, slot_offset);
    for (value, offset) in [
        (
            builder.ins().iconst(types::I32, 1),
            std::mem::offset_of!(crate::JitNativeValueSlot, refcount),
        ),
        (
            builder.ins().iconst(
                types::I32,
                i64::from(crate::JIT_NATIVE_VALUE_VIEW_DIRECT_FOREACH),
            ),
            std::mem::offset_of!(crate::JitNativeValueSlot, kind),
        ),
        (
            builder.ins().iconst(
                types::I32,
                i64::from(crate::JIT_NATIVE_DIRECT_ARRAY_ABI_VERSION),
            ),
            std::mem::offset_of!(crate::JitNativeValueSlot, flags),
        ),
        (
            builder.ins().iconst(
                types::I32,
                i64::from(crate::JIT_NATIVE_DIRECT_FOREACH_LIVE_REFERENCE),
            ),
            std::mem::offset_of!(crate::JitNativeValueSlot, reserved),
        ),
    ] {
        builder
            .ins()
            .store(MemFlagsData::new(), value, slot, offset as i32);
    }
    builder.ins().store(
        MemFlagsData::new(),
        live_source,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    builder.ins().store(
        MemFlagsData::new(),
        zero,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let encoded_index = builder
        .ins()
        .iadd_imm(next, i64::from(crate::JIT_NATIVE_DIRECT_VALUE_INDEX_BASE));
    let encoded_index = builder.ins().uextend(types::I64, encoded_index);
    Ok(builder
        .ins()
        .bor_imm(encoded_index, crate::JIT_VALUE_RUNTIME_ITERATOR_TAG as i64))
}

fn lower_total_direct_foreach_next_reference(
    builder: &mut FunctionBuilder<'_>,
    iterator: ir::Value,
    previous: ir::Value,
    retain_key: bool,
    runtime: ir::Value,
    deopt_out: ir::Value,
    value_release_commit: ir::FuncRef,
) -> (ir::Value, ir::Value, ir::Value) {
    let iterator_slot = lower_optimizing_slot_address(builder, iterator, deopt_out);
    let live_source = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        iterator_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let cursor = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        iterator_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let live_source_slot = lower_optimizing_slot_address(builder, live_source, deopt_out);
    let source = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        live_source_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let source_slot = lower_optimizing_slot_address(builder, source, deopt_out);
    let length = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        source_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let present = builder.create_block();
    let exhausted = builder.create_block();
    let done = builder.create_block();
    builder.append_block_param(done, types::I64);
    builder.append_block_param(done, types::I64);
    builder.append_block_param(done, types::I64);
    let has_value = builder.ins().icmp(IntCC::UnsignedLessThan, cursor, length);
    builder.ins().brif(has_value, present, &[], exhausted, &[]);

    builder.switch_to_block(present);
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let entries = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        source_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let entry = lower_optimizing_direct_array_entry_address(builder, entries, cursor, pointer_type);
    let key = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        entry,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, key) as i32,
    );
    let value = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        entry,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
    );
    if retain_key {
        lower_optimizing_retain(builder, key, deopt_out);
    }
    lower_optimizing_retain(builder, value, deopt_out);
    let next = builder.ins().iadd_imm(cursor, 1);
    builder.ins().store(
        MemFlagsData::new(),
        next,
        iterator_slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    let _ = builder
        .ins()
        .call(value_release_commit, &[runtime, deopt_out, previous]);
    let one = builder.ins().iconst(types::I64, 1);
    builder
        .ins()
        .jump(done, &[key.into(), value.into(), one.into()]);

    builder.switch_to_block(exhausted);
    let null = builder
        .ins()
        .iconst(types::I64, crate::jit_encode_constant(u32::MAX));
    let zero = builder.ins().iconst(types::I64, 0);
    builder
        .ins()
        .jump(done, &[null.into(), previous.into(), zero.into()]);

    builder.switch_to_block(done);
    let values = builder.block_params(done);
    (values[0], values[1], values[2])
}

fn lower_total_direct_foreach_cleanup(
    builder: &mut FunctionBuilder<'_>,
    iterator: ir::Value,
    runtime: ir::Value,
    deopt_out: ir::Value,
    value_release_commit: ir::FuncRef,
) {
    let _ = builder
        .ins()
        .call(value_release_commit, &[runtime, deopt_out, iterator]);
}

fn lower_optimizing_retain(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) {
    let retain = builder.create_block();
    let done = builder.create_block();
    let runtime = lower_is_runtime_handle(builder, value);
    builder.ins().brif(runtime, retain, &[], done, &[]);

    builder.switch_to_block(retain);
    let slot = lower_optimizing_slot_address(builder, value, deopt_out);
    let refcount = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    let retained = builder.ins().iadd_imm(refcount, 1);
    builder.ins().store(
        MemFlagsData::new(),
        retained,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    builder.ins().jump(done, &[]);

    builder.switch_to_block(done);
}

fn lower_optimizing_retain_if(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    condition: ir::Value,
    deopt_out: ir::Value,
) {
    let retain = builder.create_block();
    let done = builder.create_block();
    builder.ins().brif(condition, retain, &[], done, &[]);
    builder.switch_to_block(retain);
    lower_optimizing_retain(builder, value, deopt_out);
    builder.ins().jump(done, &[]);
    builder.switch_to_block(done);
}

/// Release an owner that was retained immediately before a compiled call.
/// The source SSA/local owner remains live, so every runtime handle is known
/// to be shared and this post-call cleanup cannot require a cold last-owner
/// transition.
fn lower_optimizing_release_call_owner(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) {
    let release = builder.create_block();
    let done = builder.create_block();
    let runtime = lower_is_runtime_handle(builder, value);
    builder.ins().brif(runtime, release, &[], done, &[]);

    builder.switch_to_block(release);
    let slot = lower_optimizing_slot_address(builder, value, deopt_out);
    let refcount = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    let released = builder.ins().iadd_imm(refcount, -1);
    builder.ins().store(
        MemFlagsData::new(),
        released,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    builder.ins().jump(done, &[]);

    builder.switch_to_block(done);
}

/// Replace one caller-owned packed slot after typed binding. An unchanged
/// native encoding transfers the existing packed owner in place; only a
/// genuinely new coerced encoding releases the superseded owner.
fn lower_optimizing_release_replaced_call_owner(
    builder: &mut FunctionBuilder<'_>,
    original: ir::Value,
    replacement: ir::Value,
    deopt_out: ir::Value,
) {
    let release = builder.create_block();
    let done = builder.create_block();
    let unchanged = builder.ins().icmp(IntCC::Equal, original, replacement);
    builder.ins().brif(unchanged, done, &[], release, &[]);
    builder.switch_to_block(release);
    lower_optimizing_release_call_owner(builder, original, deopt_out);
    builder.ins().jump(done, &[]);
    builder.switch_to_block(done);
}

/// Admit final-owner cleanup before a compiled call can execute PHP-visible
/// code. A consumed temporary receiver has no source owner after the call; if
/// its final release needs destructor/root handling, the whole call must take
/// its baseline continuation before the callee runs. Once admitted, post-call
/// cleanup is a commit and can never replay an already executed call.
fn lower_optimizing_admit_consumed_call_owner(
    _builder: &mut FunctionBuilder<'_>,
    _value: ir::Value,
    _transition: NativeOptimizingTransition<'_>,
) -> Result<(), CraneliftLoweringError> {
    // Publication owns the consumed-owner decision.  A receiver whose last
    // release can cross a destructor/cold boundary rejects the complete
    // optimizing artifact before this lowering is entered.
    Ok(())
}

/// Pack the complete positional variadic tail into the callee ABI's one
/// authoritative native array. The returned array owns one retain of every
/// element and itself has exactly one caller-side owner until the call
/// completes. No runtime binder, value decoder, or array helper participates.
fn lower_optimizing_pack_variadic_arguments(
    builder: &mut FunctionBuilder<'_>,
    values: &[ir::Value],
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    let count = builder
        .ins()
        .iconst(types::I64, i64::try_from(values.len()).unwrap_or(i64::MAX));
    let array = lower_optimizing_allocate_direct_array(builder, count, false, transition)?;
    let slot = lower_optimizing_slot_address(builder, array, transition.deopt_out);
    let pointer_type = builder.func.dfg.value_type(transition.deopt_out);
    let entries = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );
    for (index, value) in values.iter().copied().enumerate() {
        // Call operands are authoritative before packing. The variadic array
        // acquires its own owner without interpreting value bits as a
        // source-unit literal index.
        lower_optimizing_retain(builder, value, transition.deopt_out);
        let entry = builder.ins().iadd_imm(
            entries,
            i64::try_from(
                index.saturating_mul(std::mem::size_of::<crate::JitNativeDirectArrayEntry>()),
            )
            .unwrap_or(i64::MAX),
        );
        let key = builder
            .ins()
            .iconst(types::I64, i64::try_from(index).unwrap_or(i64::MAX));
        builder.ins().store(MemFlagsData::new(), key, entry, 0);
        builder.ins().store(
            MemFlagsData::new(),
            value,
            entry,
            std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
        );
    }
    builder.ins().store(
        MemFlagsData::new(),
        count,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let state = lower_direct_array_state_address(builder, array, transition.deopt_out);
    builder.ins().store(
        MemFlagsData::new(),
        count,
        state,
        std::mem::offset_of!(crate::JitNativeDirectArrayState, next_append_key) as i32,
    );
    let has_next = builder
        .ins()
        .iconst(types::I32, i64::from(!values.is_empty()));
    builder.ins().store(
        MemFlagsData::new(),
        has_next,
        state,
        std::mem::offset_of!(crate::JitNativeDirectArrayState, has_next_append_key) as i32,
    );
    Ok(array)
}

/// Pack a statically bound variadic tail while preserving PHP named-argument
/// keys. Fixed parameter binding is already complete in Region IR; only the
/// unknown names assigned to the variadic parameter reach this routine.
fn lower_optimizing_pack_bound_variadic_arguments(
    builder: &mut FunctionBuilder<'_>,
    values: &[ir::Value],
    source_arguments: &[usize],
    call_arguments: &[php_ir::instruction::IrCallArg],
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    if source_arguments.len() != values.len() {
        return Err(CraneliftLoweringError::new(
            "JIT_CRANELIFT_VARIADIC_BINDING_PLAN",
            "prepared variadic source plan does not match the native value tail",
        ));
    }
    if source_arguments.iter().all(|source| {
        call_arguments
            .get(*source)
            .is_some_and(|argument| argument.name.is_none())
    }) {
        return lower_optimizing_pack_variadic_arguments(builder, values, transition);
    }
    let count = builder
        .ins()
        .iconst(types::I64, i64::try_from(values.len()).unwrap_or(i64::MAX));
    let mut array = lower_optimizing_allocate_direct_array(builder, count, false, transition)?;
    let mut positional = 0_i64;
    for (value, source) in values.iter().copied().zip(source_arguments.iter().copied()) {
        let argument = call_arguments.get(source).ok_or_else(|| {
            CraneliftLoweringError::new(
                "JIT_CRANELIFT_VARIADIC_BINDING_PLAN",
                "prepared variadic source index is unavailable",
            )
        })?;
        if let Some(name) = argument.name.as_deref() {
            let key = lower_optimizing_static_string(builder, name.as_bytes(), transition)?;
            array =
                lower_total_native_array_insert(builder, array, key, value, true, true, transition);
            lower_optimizing_commit_owned_value(builder, key, transition);
        } else {
            let key = builder.ins().iconst(types::I64, positional);
            array = lower_total_native_array_insert_integer(
                builder,
                array,
                key,
                value,
                true,
                true,
                transition.deopt_out,
            );
            positional = positional.saturating_add(1);
        }
    }
    Ok(array)
}

/// Pack a runtime-sized positional unpack tail into the callee's one
/// authoritative variadic array. Integer unpack keys are positional and are
/// deliberately reindexed; string/named keys take the single exact baseline
/// continuation because their parameter binding is not positional.
fn lower_optimizing_admit_variadic_unpack_tail(
    _builder: &mut FunctionBuilder<'_>,
    _source_entries: ir::Value,
    _source_start: ir::Value,
    _source_length: ir::Value,
    _parameter_type: Option<&php_ir::IrReturnType>,
    _parameter_by_reference: bool,
    _transition: NativeOptimizingTransition<'_>,
) -> Result<(), CraneliftLoweringError> {
    // The entry publication scans the complete unpack tail, including key,
    // authority, reference and type requirements. Repeating that scan here
    // created an operation-local rejection path after entry.
    Ok(())
}

/// Shared direct CLIF used by baseline argument binding and by the witnessed
/// optimizing wrapper below. Optimizing consumers cannot call it indirectly:
/// they must carry `NativeReferencePayloadProof` through the wrapper.
fn lower_direct_reference_payload_unchecked(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
) -> ir::Value {
    let inspect = builder.create_block();
    let plain = builder.create_block();
    let merge = builder.create_block();
    builder.append_block_param(merge, types::I64);
    let is_reference = lower_value_has_tag(builder, value, crate::JIT_VALUE_RUNTIME_REFERENCE_TAG);
    builder.ins().brif(is_reference, inspect, &[], plain, &[]);

    builder.switch_to_block(plain);
    builder.ins().jump(merge, &[value.into()]);

    builder.switch_to_block(inspect);
    let slot = lower_optimizing_slot_address(builder, value, deopt_out);
    let payload = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    builder.ins().jump(merge, &[payload.into()]);

    builder.switch_to_block(merge);
    builder.block_params(merge)[0]
}

fn lower_optimizing_admitted_reference_scalar(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    deopt_out: ir::Value,
    _proof: NativeReferencePayloadProof,
) -> ir::Value {
    lower_direct_reference_payload_unchecked(builder, value, deopt_out)
}

// architecture: direct CLIF variadic-array constructor boundary
#[allow(clippy::too_many_arguments)]
fn lower_optimizing_pack_variadic_unpack_arguments(
    builder: &mut FunctionBuilder<'_>,
    prefix: &[ir::Value],
    source_entries: ir::Value,
    source_start: ir::Value,
    source_length: ir::Value,
    source_by_reference: bool,
    total: bool,
    transition: NativeOptimizingTransition<'_>,
) -> Result<(ir::Value, ir::Value), CraneliftLoweringError> {
    let source_tail_count = builder.ins().isub(source_length, source_start);
    let prefix_count = builder
        .ins()
        .iconst(types::I64, i64::try_from(prefix.len()).unwrap_or(i64::MAX));
    let total_count = builder.ins().iadd(prefix_count, source_tail_count);
    let array = lower_optimizing_allocate_direct_array(builder, total_count, total, transition)?;
    let slot = lower_optimizing_slot_address(builder, array, transition.deopt_out);
    let pointer_type = builder.func.dfg.value_type(transition.deopt_out);
    let output = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, aux) as i32,
    );

    for (index, value) in prefix.iter().copied().enumerate() {
        lower_optimizing_retain(builder, value, transition.deopt_out);
        let entry = builder.ins().iadd_imm(
            output,
            i64::try_from(
                index.saturating_mul(std::mem::size_of::<crate::JitNativeDirectArrayEntry>()),
            )
            .unwrap_or(i64::MAX),
        );
        let key = builder
            .ins()
            .iconst(types::I64, i64::try_from(index).unwrap_or(i64::MAX));
        builder.ins().store(MemFlagsData::new(), key, entry, 0);
        builder.ins().store(
            MemFlagsData::new(),
            value,
            entry,
            std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
        );
    }

    let scan = builder.create_block();
    let copy = builder.create_block();
    let finished = builder.create_block();
    builder.append_block_param(scan, types::I64);
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().jump(scan, &[zero.into()]);

    builder.switch_to_block(scan);
    let index = builder.block_params(scan)[0];
    let done = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, source_tail_count);
    builder.ins().brif(done, finished, &[], copy, &[]);

    builder.switch_to_block(copy);
    let source_index = builder.ins().iadd(index, source_start);
    let source = lower_optimizing_direct_array_entry_address(
        builder,
        source_entries,
        source_index,
        pointer_type,
    );
    let value = builder.ins().load(
        types::I64,
        MemFlagsData::new(),
        source,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
    );
    let value = if source_by_reference {
        value
    } else {
        lower_optimizing_admitted_reference_scalar(
            builder,
            value,
            transition.deopt_out,
            transition.reference_payload_proof,
        )
    };
    lower_optimizing_retain(builder, value, transition.deopt_out);
    let output_index = builder.ins().iadd(prefix_count, index);
    let target =
        lower_optimizing_direct_array_entry_address(builder, output, output_index, pointer_type);
    builder
        .ins()
        .store(MemFlagsData::new(), output_index, target, 0);
    builder.ins().store(
        MemFlagsData::new(),
        value,
        target,
        std::mem::offset_of!(crate::JitNativeDirectArrayEntry, value) as i32,
    );
    let next = builder.ins().iadd_imm(index, 1);
    builder.ins().jump(scan, &[next.into()]);

    builder.switch_to_block(finished);
    builder.ins().store(
        MemFlagsData::new(),
        total_count,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, payload) as i32,
    );
    let state = lower_direct_array_state_address(builder, array, transition.deopt_out);
    builder.ins().store(
        MemFlagsData::new(),
        total_count,
        state,
        std::mem::offset_of!(crate::JitNativeDirectArrayState, next_append_key) as i32,
    );
    let has_values = builder.ins().icmp_imm(IntCC::NotEqual, total_count, 0);
    let one = builder.ins().iconst(types::I32, 1);
    let zero32 = builder.ins().iconst(types::I32, 0);
    let has_values = builder.ins().select(has_values, one, zero32);
    builder.ins().store(
        MemFlagsData::new(),
        has_values,
        state,
        std::mem::offset_of!(crate::JitNativeDirectArrayState, has_next_append_key) as i32,
    );
    Ok((array, total_count))
}

/// Destroy a caller-created call-transport aggregate whose last owner is
/// statically known. The exact native release entry is already part of the
/// optimizing ABI; last-owner validation and a fallback transition would be
/// redundant here and would incorrectly make the call operation-local.
fn lower_optimizing_commit_owned_value(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) {
    let _ = builder.ins().call(
        transition.value_release_commit,
        &[transition.runtime, transition.deopt_out, value],
    );
}

fn lower_optimizing_commit_owned_value_if(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    condition: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) {
    let commit = builder.create_block();
    let done = builder.create_block();
    builder.ins().brif(condition, commit, &[], done, &[]);
    builder.switch_to_block(commit);
    lower_optimizing_commit_owned_value(builder, value, transition);
    builder.ins().jump(done, &[]);
    builder.switch_to_block(done);
}

fn lower_mark_native_roots_dirty(builder: &mut FunctionBuilder<'_>, deopt_out: ir::Value) {
    let pointer_type = builder.func.dfg.value_type(deopt_out);
    let runtime_view = lower_active_runtime_view(builder, deopt_out);
    let pending = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        runtime_view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, root_mutation_pending) as i32,
    );
    let one = builder.ins().iconst(types::I32, 1);
    builder.ins().store(MemFlagsData::new(), one, pending, 0);
}

fn lower_optimizing_release(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) -> Result<(), CraneliftLoweringError> {
    lower_direct_release_with_commit(
        builder,
        value,
        transition.runtime,
        transition.deopt_out,
        transition.value_release_commit,
    )
}

fn lower_direct_release_with_commit(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    runtime: ir::Value,
    deopt_out: ir::Value,
    value_release_commit: ir::FuncRef,
) -> Result<(), CraneliftLoweringError> {
    let inspect = builder.create_block();
    let release = builder.create_block();
    let last = builder.create_block();
    let done = builder.create_block();
    let is_runtime = lower_is_runtime_handle(builder, value);
    builder.ins().brif(is_runtime, inspect, &[], done, &[]);

    builder.switch_to_block(inspect);
    let slot = lower_optimizing_slot_address(builder, value, deopt_out);
    let refcount = builder.ins().load(
        types::I32,
        MemFlagsData::new(),
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    let is_last = builder.ins().icmp_imm(IntCC::Equal, refcount, 1);
    builder.ins().brif(is_last, last, &[], release, &[]);

    builder.switch_to_block(release);
    let released = builder.ins().iadd_imm(refcount, -1);
    builder.ins().store(
        MemFlagsData::new(),
        released,
        slot,
        std::mem::offset_of!(crate::JitNativeValueSlot, refcount) as i32,
    );
    builder.ins().jump(done, &[]);

    builder.switch_to_block(last);
    // Publication rejects non-direct final owners. The commit function is the
    // total native release ABI for the admitted direct scalar/reference/array
    // family and recursively consumes its authoritative children.
    let _ = builder
        .ins()
        .call(value_release_commit, &[runtime, deopt_out, value]);
    builder.ins().jump(done, &[]);

    builder.switch_to_block(done);
    Ok(())
}

fn lower_optimizing_type_predicate(
    builder: &mut FunctionBuilder<'_>,
    operation: StableTypePredicateBuiltin,
    value: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    let value = lower_optimizing_reference_scalar(builder, value, false, transition)?;
    let is_null = builder
        .ins()
        .icmp_imm(IntCC::Equal, value, crate::jit_encode_constant(u32::MAX));
    let is_false = builder.ins().icmp_imm(
        IntCC::Equal,
        value,
        crate::jit_encode_constant(crate::JIT_VALUE_FALSE),
    );
    let is_true = builder.ins().icmp_imm(
        IntCC::Equal,
        value,
        crate::jit_encode_constant(crate::JIT_VALUE_TRUE),
    );
    let is_bool = builder.ins().bor(is_false, is_true);
    let is_int = lower_optimizing_integer_candidate(builder, value, transition.deopt_out).0;
    let has_kind =
        |builder: &mut FunctionBuilder<'_>, tag| lower_value_has_tag(builder, value, tag);
    let object_type_match = if matches!(
        operation,
        StableTypePredicateBuiltin::Countable | StableTypePredicateBuiltin::Iterable
    ) {
        let object = has_kind(builder, crate::JIT_VALUE_RUNTIME_OBJECT_TAG);
        let inspect = builder.create_block();
        let absent = builder.create_block();
        let done = builder.create_block();
        let bool_type = builder.func.dfg.value_type(object);
        builder.append_block_param(done, bool_type);
        builder.ins().brif(object, inspect, &[], absent, &[]);

        builder.switch_to_block(inspect);
        let slot = lower_optimizing_slot_address(builder, value, transition.deopt_out);
        let flags = builder.ins().load(
            types::I32,
            MemFlagsData::new(),
            slot,
            std::mem::offset_of!(crate::JitNativeValueSlot, flags) as i32,
        );
        let expected = match operation {
            StableTypePredicateBuiltin::Countable => crate::JIT_NATIVE_OBJECT_COUNTABLE,
            StableTypePredicateBuiltin::Iterable => crate::JIT_NATIVE_OBJECT_TRAVERSABLE,
            _ => unreachable!("object type flags are requested only for interface predicates"),
        };
        let classified = builder.ins().band_imm(flags, i64::from(expected));
        let classified = builder.ins().icmp_imm(IntCC::NotEqual, classified, 0);
        builder.ins().jump(done, &[classified.into()]);

        builder.switch_to_block(absent);
        let not_classified = builder.ins().iconst(bool_type, 0);
        builder.ins().jump(done, &[not_classified.into()]);

        builder.switch_to_block(done);
        Some(builder.block_params(done)[0])
    } else {
        None
    };
    let matched = match operation {
        StableTypePredicateBuiltin::Null => is_null,
        StableTypePredicateBuiltin::Bool => is_bool,
        StableTypePredicateBuiltin::Int => is_int,
        StableTypePredicateBuiltin::Float => has_kind(builder, crate::JIT_VALUE_RUNTIME_FLOAT_TAG),
        StableTypePredicateBuiltin::String => {
            has_kind(builder, crate::JIT_VALUE_RUNTIME_STRING_TAG)
        }
        StableTypePredicateBuiltin::Array => has_kind(builder, crate::JIT_VALUE_RUNTIME_ARRAY_TAG),
        StableTypePredicateBuiltin::Object => {
            let object = has_kind(builder, crate::JIT_VALUE_RUNTIME_OBJECT_TAG);
            let callable = has_kind(builder, crate::JIT_VALUE_RUNTIME_CALLABLE_TAG);
            let generator = has_kind(builder, crate::JIT_VALUE_RUNTIME_GENERATOR_TAG);
            let fiber = has_kind(builder, crate::JIT_VALUE_RUNTIME_FIBER_TAG);
            let object = builder.ins().bor(object, callable);
            let object = builder.ins().bor(object, generator);
            builder.ins().bor(object, fiber)
        }
        StableTypePredicateBuiltin::Resource => {
            has_kind(builder, crate::JIT_VALUE_RUNTIME_RESOURCE_TAG)
        }
        StableTypePredicateBuiltin::Scalar => {
            let float = has_kind(builder, crate::JIT_VALUE_RUNTIME_FLOAT_TAG);
            let string = has_kind(builder, crate::JIT_VALUE_RUNTIME_STRING_TAG);
            let scalar = builder.ins().bor(is_bool, is_int);
            let scalar = builder.ins().bor(scalar, float);
            builder.ins().bor(scalar, string)
        }
        StableTypePredicateBuiltin::Countable => {
            let array = has_kind(builder, crate::JIT_VALUE_RUNTIME_ARRAY_TAG);
            builder.ins().bor(
                array,
                object_type_match.expect("countable object classification"),
            )
        }
        StableTypePredicateBuiltin::Iterable => {
            let array = has_kind(builder, crate::JIT_VALUE_RUNTIME_ARRAY_TAG);
            let generator = has_kind(builder, crate::JIT_VALUE_RUNTIME_GENERATOR_TAG);
            let iterable = builder.ins().bor(array, generator);
            builder.ins().bor(
                iterable,
                object_type_match.expect("iterable object classification"),
            )
        }
    };
    Ok(encode_native_bool(builder, matched))
}

fn lower_numeric_ascii_whitespace(builder: &mut FunctionBuilder<'_>, byte: ir::Value) -> ir::Value {
    let at_least_tab = builder
        .ins()
        .icmp_imm(IntCC::UnsignedGreaterThanOrEqual, byte, 9);
    let at_most_carriage = builder
        .ins()
        .icmp_imm(IntCC::UnsignedLessThanOrEqual, byte, 13);
    let control = builder.ins().band(at_least_tab, at_most_carriage);
    let space = builder.ins().icmp_imm(IntCC::Equal, byte, 32);
    builder.ins().bor(control, space)
}

fn lower_numeric_ascii_digit(builder: &mut FunctionBuilder<'_>, byte: ir::Value) -> ir::Value {
    let at_least_zero =
        builder
            .ins()
            .icmp_imm(IntCC::UnsignedGreaterThanOrEqual, byte, i64::from(b'0'));
    let at_most_nine =
        builder
            .ins()
            .icmp_imm(IntCC::UnsignedLessThanOrEqual, byte, i64::from(b'9'));
    builder.ins().band(at_least_zero, at_most_nine)
}

fn lower_optimizing_is_numeric(
    builder: &mut FunctionBuilder<'_>,
    value: ir::Value,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    let value = lower_optimizing_reference_scalar(builder, value, false, transition)?;
    let inspect_string = builder.create_block();
    let leading = builder.create_block();
    let inspect_leading = builder.create_block();
    let sign = builder.create_block();
    let mantissa = builder.create_block();
    let inspect_mantissa = builder.create_block();
    let fraction = builder.create_block();
    let inspect_fraction = builder.create_block();
    let after_mantissa = builder.create_block();
    let inspect_exponent = builder.create_block();
    let exponent_sign = builder.create_block();
    let inspect_exponent_sign = builder.create_block();
    let exponent_digits = builder.create_block();
    let inspect_exponent_digit = builder.create_block();
    let exponent_done = builder.create_block();
    let trailing = builder.create_block();
    let inspect_trailing = builder.create_block();
    let yes = builder.create_block();
    let no = builder.create_block();
    let merge = builder.create_block();
    builder.append_block_param(leading, types::I64);
    builder.append_block_param(sign, types::I64);
    builder.append_block_param(mantissa, types::I64);
    builder.append_block_param(mantissa, types::I64);
    builder.append_block_param(fraction, types::I64);
    builder.append_block_param(fraction, types::I64);
    builder.append_block_param(after_mantissa, types::I64);
    builder.append_block_param(after_mantissa, types::I64);
    builder.append_block_param(exponent_sign, types::I64);
    builder.append_block_param(exponent_digits, types::I64);
    builder.append_block_param(exponent_digits, types::I64);
    builder.append_block_param(exponent_done, types::I64);
    builder.append_block_param(exponent_done, types::I64);
    builder.append_block_param(trailing, types::I64);
    builder.append_block_param(merge, types::I8);

    let integer = lower_optimizing_integer_candidate(builder, value, transition.deopt_out).0;
    let float = lower_value_has_tag(builder, value, crate::JIT_VALUE_RUNTIME_FLOAT_TAG);
    let scalar_numeric = builder.ins().bor(integer, float);
    builder
        .ins()
        .brif(scalar_numeric, yes, &[], inspect_string, &[]);

    builder.switch_to_block(inspect_string);
    let string = lower_value_has_tag(builder, value, crate::JIT_VALUE_RUNTIME_STRING_TAG);
    let parse_string = builder.create_block();
    builder.ins().brif(string, parse_string, &[], no, &[]);

    builder.switch_to_block(parse_string);
    let (length, bytes) = lower_optimizing_string_descriptor(builder, value, transition)?;
    let zero = builder.ins().iconst(types::I64, 0);
    builder.ins().jump(leading, &[zero.into()]);

    builder.switch_to_block(leading);
    let index = builder.block_params(leading)[0];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder.ins().brif(exhausted, no, &[], inspect_leading, &[]);

    builder.switch_to_block(inspect_leading);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let whitespace = lower_numeric_ascii_whitespace(builder, byte);
    let next = builder.ins().iadd_imm(index, 1);
    builder
        .ins()
        .brif(whitespace, leading, &[next.into()], sign, &[index.into()]);

    builder.switch_to_block(sign);
    let index = builder.block_params(sign)[0];
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let plus = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'+'));
    let minus = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'-'));
    let signed = builder.ins().bor(plus, minus);
    let next = builder.ins().iadd_imm(index, 1);
    let start = builder.ins().select(signed, next, index);
    builder.ins().jump(mantissa, &[start.into(), zero.into()]);

    builder.switch_to_block(mantissa);
    let index = builder.block_params(mantissa)[0];
    let digits = builder.block_params(mantissa)[1];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder.ins().brif(
        exhausted,
        after_mantissa,
        &[index.into(), digits.into()],
        inspect_mantissa,
        &[],
    );

    builder.switch_to_block(inspect_mantissa);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let digit = lower_numeric_ascii_digit(builder, byte);
    let mantissa_digit = builder.create_block();
    let inspect_dot = builder.create_block();
    builder
        .ins()
        .brif(digit, mantissa_digit, &[], inspect_dot, &[]);

    builder.switch_to_block(mantissa_digit);
    let next = builder.ins().iadd_imm(index, 1);
    let next_digits = builder.ins().iadd_imm(digits, 1);
    builder
        .ins()
        .jump(mantissa, &[next.into(), next_digits.into()]);

    builder.switch_to_block(inspect_dot);
    let dot = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'.'));
    let after_dot = builder.ins().iadd_imm(index, 1);
    builder.ins().brif(
        dot,
        fraction,
        &[after_dot.into(), digits.into()],
        after_mantissa,
        &[index.into(), digits.into()],
    );

    builder.switch_to_block(fraction);
    let index = builder.block_params(fraction)[0];
    let digits = builder.block_params(fraction)[1];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder.ins().brif(
        exhausted,
        after_mantissa,
        &[index.into(), digits.into()],
        inspect_fraction,
        &[],
    );

    builder.switch_to_block(inspect_fraction);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let digit = lower_numeric_ascii_digit(builder, byte);
    let fraction_digit = builder.create_block();
    builder.ins().brif(
        digit,
        fraction_digit,
        &[],
        after_mantissa,
        &[index.into(), digits.into()],
    );

    builder.switch_to_block(fraction_digit);
    let next = builder.ins().iadd_imm(index, 1);
    let next_digits = builder.ins().iadd_imm(digits, 1);
    builder
        .ins()
        .jump(fraction, &[next.into(), next_digits.into()]);

    builder.switch_to_block(after_mantissa);
    let index = builder.block_params(after_mantissa)[0];
    let digits = builder.block_params(after_mantissa)[1];
    let has_digits = builder.ins().icmp_imm(IntCC::NotEqual, digits, 0);
    builder
        .ins()
        .brif(has_digits, inspect_exponent, &[], no, &[]);

    builder.switch_to_block(inspect_exponent);
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    let inspect_exponent_byte = builder.create_block();
    builder
        .ins()
        .brif(exhausted, yes, &[], inspect_exponent_byte, &[]);

    builder.switch_to_block(inspect_exponent_byte);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let lower_e = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'e'));
    let upper_e = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'E'));
    let exponent = builder.ins().bor(lower_e, upper_e);
    let next = builder.ins().iadd_imm(index, 1);
    builder.ins().brif(
        exponent,
        exponent_sign,
        &[next.into()],
        trailing,
        &[index.into()],
    );

    builder.switch_to_block(exponent_sign);
    let index = builder.block_params(exponent_sign)[0];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder
        .ins()
        .brif(exhausted, no, &[], inspect_exponent_sign, &[]);

    builder.switch_to_block(inspect_exponent_sign);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let plus = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'+'));
    let minus = builder.ins().icmp_imm(IntCC::Equal, byte, i64::from(b'-'));
    let signed = builder.ins().bor(plus, minus);
    let next = builder.ins().iadd_imm(index, 1);
    let start = builder.ins().select(signed, next, index);
    builder
        .ins()
        .jump(exponent_digits, &[start.into(), zero.into()]);

    builder.switch_to_block(exponent_digits);
    let index = builder.block_params(exponent_digits)[0];
    let digits = builder.block_params(exponent_digits)[1];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder.ins().brif(
        exhausted,
        exponent_done,
        &[index.into(), digits.into()],
        inspect_exponent_digit,
        &[],
    );

    builder.switch_to_block(inspect_exponent_digit);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let digit = lower_numeric_ascii_digit(builder, byte);
    let exponent_digit = builder.create_block();
    builder.ins().brif(
        digit,
        exponent_digit,
        &[],
        exponent_done,
        &[index.into(), digits.into()],
    );

    builder.switch_to_block(exponent_digit);
    let next = builder.ins().iadd_imm(index, 1);
    let next_digits = builder.ins().iadd_imm(digits, 1);
    builder
        .ins()
        .jump(exponent_digits, &[next.into(), next_digits.into()]);

    builder.switch_to_block(exponent_done);
    let index = builder.block_params(exponent_done)[0];
    let digits = builder.block_params(exponent_done)[1];
    let has_digits = builder.ins().icmp_imm(IntCC::NotEqual, digits, 0);
    builder
        .ins()
        .brif(has_digits, trailing, &[index.into()], no, &[]);

    builder.switch_to_block(trailing);
    let index = builder.block_params(trailing)[0];
    let exhausted = builder
        .ins()
        .icmp(IntCC::UnsignedGreaterThanOrEqual, index, length);
    builder
        .ins()
        .brif(exhausted, yes, &[], inspect_trailing, &[]);

    builder.switch_to_block(inspect_trailing);
    let at = builder.ins().iadd(bytes, index);
    let byte = builder.ins().load(types::I8, MemFlagsData::new(), at, 0);
    let whitespace = lower_numeric_ascii_whitespace(builder, byte);
    let next = builder.ins().iadd_imm(index, 1);
    builder
        .ins()
        .brif(whitespace, trailing, &[next.into()], no, &[]);

    builder.switch_to_block(yes);
    let yes_value = builder.ins().iconst(types::I8, 1);
    builder.ins().jump(merge, &[yes_value.into()]);
    builder.switch_to_block(no);
    let no_value = builder.ins().iconst(types::I8, 0);
    builder.ins().jump(merge, &[no_value.into()]);
    builder.switch_to_block(merge);
    let result = builder.block_params(merge)[0];
    Ok(encode_native_bool(builder, result))
}

fn lower_optimizing_error_reporting(
    builder: &mut FunctionBuilder<'_>,
    requested: Option<ir::Value>,
    transition: NativeOptimizingTransition<'_>,
) -> Result<ir::Value, CraneliftLoweringError> {
    let pointer_type = builder.func.dfg.value_type(transition.deopt_out);
    let view = lower_active_runtime_view(builder, transition.deopt_out);
    let capability = builder.ins().load(
        pointer_type,
        MemFlagsData::new(),
        view,
        std::mem::offset_of!(crate::JitNativeRuntimeView, error_reporting) as i32,
    );
    let current = builder
        .ins()
        .load(types::I64, MemFlagsData::new(), capability, 0);
    if let Some(requested) = requested {
        let requested = lower_optimizing_require_immediate_integer(builder, requested, transition)?;
        builder
            .ins()
            .store(MemFlagsData::new(), requested, capability, 0);
    }
    Ok(current)
}

// Fixed builtin publication admits only handlers with three possible
// outcomes: a native value, a PHP-visible throw/runtime diagnostic, or an ABI
// contract violation. Unknown statuses are converted to ABI_MISMATCH locally;
// they never enter the generic continuation adapter.
macro_rules! emit_total_exact_runtime_value {
    ($module:expr, $builder:expr, $helper:expr, $arguments:expr, $transition:expr, $missing:expr $(,)?) => {{
        let helper = ($helper).ok_or_else(|| {
            CraneliftLoweringError::new("JIT_CRANELIFT_REJECT_NATIVE_OPERATION", $missing)
        })?;
        let call = call_native_helper($module, $builder, helper, $arguments);
        let control = $builder.inst_results(call)[0];
        let value = $builder.inst_results(call)[1];
        let status = $builder.ins().ireduce(types::I32, control);
        let detail = $builder.ins().ushr_imm(control, 32);
        let detail = $builder.ins().ireduce(types::I32, detail);
        let returned = $builder.create_block();
        let classify_control = $builder.create_block();
        let throw_control = $builder.create_block();
        let runtime_error_control = $builder.create_block();
        let contract_violation = $builder.create_block();
        let is_return = $builder.ins().icmp_imm(
            IntCC::Equal,
            status,
            i64::from(crate::JitCallStatus::RETURN.0),
        );
        $builder
            .ins()
            .brif(is_return, returned, &[], classify_control, &[]);

        $builder.switch_to_block(classify_control);
        let is_throw = $builder.ins().icmp_imm(
            IntCC::Equal,
            status,
            i64::from(crate::JitCallStatus::THROW.0),
        );
        $builder
            .ins()
            .brif(is_throw, throw_control, &[], runtime_error_control, &[]);

        $builder.switch_to_block(throw_control);
        $transition.emit_exact_throw($builder, detail, value)?;

        $builder.switch_to_block(runtime_error_control);
        let is_runtime_error = $builder.ins().icmp_imm(
            IntCC::Equal,
            status,
            i64::from(crate::JitCallStatus::RUNTIME_ERROR.0),
        );
        let publish_runtime_error = $builder.create_block();
        $builder.ins().brif(
            is_runtime_error,
            publish_runtime_error,
            &[],
            contract_violation,
            &[],
        );
        $builder.switch_to_block(publish_runtime_error);
        $transition.emit_exact_runtime_error($builder, detail, value)?;

        $builder.switch_to_block(contract_violation);
        let abi_mismatch = $builder
            .ins()
            .iconst(types::I32, i64::from(crate::JitCallStatus::ABI_MISMATCH.0));
        let continuation = $builder
            .ins()
            .iconst(types::I32, i64::from($transition.continuation_id));
        let source_status = $builder.ins().uextend(types::I64, status);
        $transition.emit_control($builder, abi_mismatch, continuation, source_status)?;

        $builder.switch_to_block(returned);
        Ok::<ir::Value, CraneliftLoweringError>(value)
    }};
}

